"use strict";(self.webpackChunkabc2book=self.webpackChunkabc2book||[]).push([[199],{96199:(e,t,i)=>{i.r(t),i.d(t,{default:()=>s,singingModules:()=>a,theoryModules:()=>o});const n=[{id:"singing-breath-low-01",title:"Low breath, easy belly",track:"breath",kind:"singing_tip",difficulty:0,tags:["breath","foundation","folk"],prerequisites:[],estimateMinutes:2,body:"Notice where air goes when you breathe in for a ballad or session tune. Many singers lift the shoulders without meaning to\u2014and that tightens the throat. A low, quiet belly breath gives you a steady base without looking like you are \u201cperforming breathing.\u201d Let the ribs widen sideways; keep shoulders soft and jaw loose.",tryThis:"Breathe in through the nose for four counts, feel your lower ribs widen, then release on a gentle hum."},{id:"singing-breath-phrase-01",title:"Plan the phrase, not the gulp",track:"breath",kind:"singing_tip",difficulty:2,tags:["breath","phrasing","lyrics"],prerequisites:["singing-breath-low-01"],estimateMinutes:2,body:"Notice how a long chorus line in a trad song can force a mid-phrase grab for air. Map where the tune breathes naturally\u2014often at a comma in the lyrics or between repeated lines. Mark those spots on your lyric sheet so the breath supports the story instead of cutting a word short or rushing the melody.",tryThis:"Sing one phrase of a tune you know, and mark where you breathe before you add the next."},{id:"singing-breath-rebound-01",title:"Let the breath bounce back",track:"breath",kind:"singing_tip",difficulty:3,tags:["breath","support","session"],prerequisites:["singing-breath-phrase-01"],estimateMinutes:2,body:"Notice the small rebound after a soft exhale on \u201cah\u201d or a hum. Folk singing at a session often asks for phrase after phrase\u2014you do not need a huge inhalation each time. A quick, low refill, like the breath returning after speaking a sentence, keeps tone steady through chorus after chorus without running out or tightening up.",tryThis:"Hum a comfortable pitch, release, and feel the rebound inhale arrive without lifting your chest."}].concat([{id:"singing-warmup-hum-01",title:"Gentle hum wake-up",track:"warmup",kind:"warmup_idea",difficulty:1,tags:["warmup","hum","gentle"],prerequisites:[],estimateMinutes:2,body:"Notice how a soft closed-mouth hum can warm your voice before a session better than jumping straight into a loud chorus. Start in a comfortable speaking range and slide slowly up and down by a few notes. Keep lips lightly together and jaw loose\u2014think of buzzing into a mug. If anything feels scratchy, stay smaller and quieter.",tryThis:"Hum up and down five times on \u201cmm,\u201d keeping volume barely above a whisper."},{id:"singing-warmup-liptrill-01",title:"Loose lip trill",track:"warmup",kind:"warmup_idea",difficulty:2,tags:["warmup","lip-trill","breath"],prerequisites:["singing-warmup-hum-01"],estimateMinutes:2,body:"Notice whether your lips flutter easily on a lip trill or feel stiff after a day of talking. This classic warmup connects breath to sound without much throat effort\u2014ideal before reels or songs with quick turns of phrase. If the trill sputters, lighten the air and try a smaller pitch range instead of pushing harder.",tryThis:"Glide a lip trill from your lowest comfortable note up through your speaking range and back down."},{id:"singing-warmup-ngah-01",title:"Ng\u2013ah tongue release",track:"warmup",kind:"warmup_idea",difficulty:3,tags:["warmup","vowels","forward-tone"],prerequisites:["singing-warmup-liptrill-01"],estimateMinutes:2,body:"Notice the tongue tip resting lightly behind your top teeth on \u201cng,\u201d then opening to \u201cah\u201d without the jaw dropping wide. This combo helps folk singers find a forward, clear tone before tackling consonant-heavy lyrics. Keep it slow and easy\u2014no pushing for volume. Stop if your throat feels tight or hoarse.",tryThis:"Sing \u201cng\u2013ah\u201d on a single pitch five times, then move up by half steps if it feels comfortable."},{id:"singing-warmup-pulse-01",title:"Pulse on one vowel",track:"warmup",kind:"warmup_idea",difficulty:4,tags:["warmup","support","dance-tunes"],prerequisites:["singing-warmup-ngah-01"],estimateMinutes:2,body:"Notice how repeating a vowel in short, gentle pulses trains breath support for dance tunes and steady choruses. Pick one pitch and sing \u201coo\u201d or \u201cee\u201d in four quick-soft pulses, then one longer note. You should feel the belly engage slightly on each pulse\u2014not a hard squeeze, just steady. Ease off if you feel any strain.",tryThis:"Practice four gentle \u201coo\u201d pulses followed by a held \u201coo\u201d on one comfortable pitch."},{id:"singing-warmup-octave-01",title:"Easy octave glide",track:"warmup",kind:"warmup_idea",difficulty:5,tags:["warmup","range","glide"],prerequisites:["singing-warmup-pulse-01"],estimateMinutes:2,body:"Notice whether your voice moves smoothly across an octave on \u201coo\u201d or \u201cng,\u201d or catches in the middle\u2014often where chest and head mix. Folk melodies span wider than you think; a slow octave glide maps that path before you open a tune. Stop if anything feels strained; smaller intervals work just as well for warming up.",tryThis:"Glide from a low \u201coo\u201d up one octave and back down on one breath, as lightly as you can."}],[{id:"singing-tone-mask-01",title:"Buzz in the mask",track:"tone",kind:"singing_tip",difficulty:2,tags:["tone","resonance","acoustics"],prerequisites:[],estimateMinutes:2,body:"Notice a slight tingle in your lips, nose, and cheekbones when tone is forward\u2014not pinned in the throat. Folk singers in rooms with hard acoustics benefit from this \u201cmask\u201d feeling; the sound carries without pushing. A soft hum or \u201cng\u201d often finds it faster than a wide open vowel. If tone feels throaty, go back to humming and lighten the air.",tryThis:"Hum and notice the vibration in your lips and nose before you open to \u201cah.\u201d"},{id:"singing-tone-vowels-01",title:"Match vowels through the line",track:"tone",kind:"singing_tip",difficulty:3,tags:["tone","vowels","legibility"],prerequisites:["singing-tone-mask-01"],estimateMinutes:2,body:"Notice whether \u201cee\u201d and \u201cah\u201d in the same chorus feel like the same voice or like two different singers. Consistent vowel shape keeps a trad line legible across a room. Shape the mouth for each vowel once, then sing slowly through tricky words from your tune. The goal is one recognizable tone color, not identical mouth positions for every syllable.",tryThis:"Sing \u201cee\u2013eh\u2013ah\u2013oh\u2013oo\u201d slowly on one pitch, keeping tone color steady."},{id:"singing-tone-onset-01",title:"Soft onset, clear start",track:"tone",kind:"singing_tip",difficulty:4,tags:["tone","onset","ballads"],prerequisites:["singing-tone-vowels-01"],estimateMinutes:2,body:"Notice how you begin each note\u2014does the sound pop in with a tiny glottal hitch, or arrive like breath turning into tone? A gentle coordinated onset helps ballads and slow airs start cleanly. Folk songs often begin on a stressed syllable; practice that entry softly before you add weight. Hard onsets tire the voice faster over a long night.",tryThis:"Sing several \u201cah\u201d starts on one pitch, aiming for breath and tone to meet without a click."}],[{id:"singing-pitch-drone-01",title:"Drone as your anchor",track:"pitch",kind:"singing_tip",difficulty:2,tags:["pitch","drone","modal"],prerequisites:[],estimateMinutes:2,body:"Notice how a sustained drone\u2014or a friend humming the tonic\u2014gives your ear a home base in modal or session tunes. Match your starting note to that drone before you sing the melody; small slips are easier to catch early. This is especially helpful in keys with fewer obvious \u201cleading\u201d pulls. You are not chasing perfection\u2014just noticing when you drift.",tryThis:"Listen to a low drone (or hum one yourself), then sing the first line of a tune against it."},{id:"singing-pitch-final-01",title:"Land the last note",track:"pitch",kind:"singing_tip",difficulty:3,tags:["pitch","phrasing","intervals"],prerequisites:["singing-pitch-drone-01"],estimateMinutes:2,body:"Notice where each phrase ends in a tune you know\u2014often on the tonic or dominant. Folk melodies can wander; the final note of a line tells the room you are secure. Mark those landing notes and check they settle, not slide past. Singing only the endings is a quick way to build confidence before a full chorus.",tryThis:"Sing only the final note of each phrase in a chorus, holding it steady for two beats."},{id:"singing-pitch-chordtones-01",title:"Outline the harmony",track:"pitch",kind:"singing_tip",difficulty:5,tags:["pitch","harmony","ear-training"],prerequisites:["singing-pitch-final-01"],estimateMinutes:2,body:"Notice the third and fifth of the home chord under your melody\u2014they hint at major vs minor and whether a line feels bright or melancholic. You do not need perfect theory; humming root\u2013third\u2013fifth before a tune wakes your ear to the shape of the song. Common in sessions when everyone finds the same key by ear and locks in together.",tryThis:"Hum the root, third, and fifth of the key, then sing the first phrase of your tune."}],[{id:"singing-diction-cons-01",title:"Consonants on the beat",track:"diction",kind:"singing_tip",difficulty:2,tags:["diction","consonants","lyrics"],prerequisites:[],estimateMinutes:2,body:"Notice how crisp consonants\u2014t, k, d\u2014in a fast jig or chorus help listeners catch words in a noisy pub. Folk lyrics carry the story; you need consonants clear but not choked. Tongue tip stays light; let the vowel carry most of the tone after the consonant pops. Over-articulating every letter can sound stiff\u2014aim for rhythm first, clarity second.",tryThis:"Speak the first line of a tune rhythmically, exaggerating final consonants slightly, then sing it."}],[{id:"singing-expression-keyword-01",title:"One word, full meaning",track:"expression",kind:"singing_tip",difficulty:1,tags:["expression","storytelling","lyrics"],prerequisites:[],estimateMinutes:2,body:"Notice a single keyword in each verse\u2014\u201chome,\u201d \u201csea,\u201d \u201ctrue\u201d\u2014and how your tone changes when you mean it. Folk songs often hinge on one plain word rather than flashy technique. Pick that word before you sing the line; let the rest stay conversational. Listeners remember the word you believed, not the loudest note in the room.",tryThis:"Sing one line three times, changing only the color on your chosen keyword."},{id:"singing-expression-dynamics-01",title:"Dynamics follow the story",track:"expression",kind:"singing_tip",difficulty:3,tags:["expression","dynamics","session"],prerequisites:["singing-expression-keyword-01"],estimateMinutes:2,body:"Notice whether louder always means better in a chorus everyone knows. Pull back on a verse so the refrain has somewhere to grow\u2014or stay intimate on a sad air when the room is quiet. Session dynamics are collective; leave space for others. A soft verse often makes the whole room lean in before the chorus lands.",tryThis:"Sing a verse softly and the chorus one step louder, without pushing your top volume."},{id:"singing-style-ornament-01",title:"Ornament with intent",track:"style",kind:"singing_tip",difficulty:6,tags:["style","ornament","tradition"],prerequisites:["singing-expression-dynamics-01"],estimateMinutes:2,body:"Notice ornaments\u2014cuts, rolls, quick turns\u2014that fit the tradition of your tune vs ones that feel pasted on. A single well-placed turn on a held note often beats a run on every syllable. Listen to a recording you love and map one ornament you might borrow sparingly. Less ornament usually sounds more authentic in a pub session.",tryThis:"Listen to one recorded phrase, then try a single light ornament on the same spot in your tune."}],[{id:"singing-health-hydrate-01",title:"Sip before you strain",track:"health",kind:"singing_tip",difficulty:0,tags:["health","hydration","comfort"],prerequisites:[],estimateMinutes:2,body:"Notice dry throat scratch before a long session\u2014not after discomfort has set in. Room air, talk, and a pint all dehydrate vocal folds. Water helps comfort; it is not a cure, but singing on a wetter throat usually feels easier. Sip steadily during breaks rather than chugging right before you sing. Warm tea can soothe, but very hot drinks are best saved for after.",tryThis:"Sip water now and keep it within reach for your next practice."},{id:"singing-health-stop-01",title:"Stop when it hurts",track:"health",kind:"singing_tip",difficulty:1,tags:["health","rest","safety"],prerequisites:[],estimateMinutes:2,body:"Notice hoarseness, pain, or a sudden need to clear your throat\u2014that is your signal to rest, not push through. Folk sessions reward stamina, but your voice is the instrument. Whispering and forcing low notes often strain more than quiet humming. Rest today; hum gently tomorrow if it feels clear. Persistent hoarseness deserves a break from singing and professional advice.",tryThis:"Stop singing if you feel pain or sudden hoarseness, and rest your voice for the day."},{id:"singing-health-pace-01",title:"Pace a long night",track:"health",kind:"singing_tip",difficulty:4,tags:["health","stamina","session"],prerequisites:["singing-health-stop-01"],estimateMinutes:2,body:"Notice how session singers rotate tunes and chatter\u2014your voice needs those micro-rests too. Singing ten loud choruses back-to-back fatigues even strong voices. Plan quieter songs between belters, and hum between sets to stay warm without full volume. Pacing is a skill: you can enjoy the whole night and still sound good on the last tune.",tryThis:"Count one fully quiet break between every three songs in your next practice set."}]),o=[].concat([{id:"foundations-pitch-01",title:"The Staff, Clefs, and Pitch Names",track:"foundations",kind:"theory_lesson",difficulty:0,tags:["notation","pitch","clefs"],prerequisites:[],estimateMinutes:4,body:"Western music notation is written on a staff of five horizontal lines. Each line and each space between lines represents a different pitch. Notes can also sit above or below the staff, connected by ledger lines when they fall outside the five-line frame.\n\nThe treble clef (G clef) wraps around the second line from the bottom, marking that line as G above middle C. It is the standard clef for fiddle, flute, whistle, and most melody lines in tune books. The bass clef (F clef) places F below middle C on the fourth line and is common for piano left hand, cello, and accordion bass. Middle C sits on a ledger line between the two staves when they are joined in piano or harp notation.\n\nPitch names repeat in cycles of A through G. On the treble staff, the spaces spell F-A-C-E from bottom to top, and the lines are E-G-B-D-F. Learning one clef well is enough to start reading tunes; many trad players begin with treble and pick up bass later if they play piano or accompaniment.",tryThis:"",quizzes:[{id:"foundations-pitch-01-q1",type:"mcq",prompt:"Which clef is most commonly used for fiddle and whistle melody lines in tune books?",difficulty:0,choices:[{id:"a",text:"Treble clef (G clef)",correct:!0},{id:"b",text:"Bass clef (F clef)"},{id:"c",text:"Alto clef (C clef on middle line)"},{id:"d",text:"Percussion clef"}],explain:"Treble clef is the standard for high-pitched melody instruments and appears in most ABC and printed tune collections."},{id:"foundations-pitch-01-q2",type:"truefalse",prompt:"Middle C can appear on a ledger line between treble and bass staves in piano notation.",difficulty:0,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"In grand staff notation, middle C sits on a ledger line between the treble and bass staves, linking the two clefs."}]},{id:"foundations-rhythm-01",title:"Note Durations and Time Signatures",track:"foundations",kind:"theory_lesson",difficulty:0,tags:["rhythm","meter","notation"],prerequisites:[],estimateMinutes:4,body:"Rhythm tells you how long each note lasts relative to the beat. A whole note is the longest common value; a half note lasts half as long; a quarter note half again; and eighth notes move twice as fast as quarters. In ABC notation you will see these as note lengths after the letter: L:1/8 sets the default unit, and a2 means a note twice that length.\n\nThe time signature appears at the start of a tune and tells you how beats group into measures. 4/4 (common time) means four quarter-note beats per bar. 6/8 groups beats in two, each beat subdivided into three eighth notes \u2014 the feel of a jig. 2/4 and 2/2 (cut time) drive reels and many hornpipes with a steady two-beat pulse. 3/4 carries waltzes with three beats per bar.\n\nThe tempo marking (often in Italian) suggests speed, but the time signature defines the rhythmic grid. When you tap your foot to a reel, you are feeling the beat structure; when you count \u201cONE-and TWO-and\u201d in a jig, you are feeling compound meter. Matching foot-tap to written meter makes sight-reading sessions far less mysterious.",tryThis:"",quizzes:[{id:"foundations-rhythm-01-q1",type:"mcq",prompt:"What does a 6/8 time signature most strongly suggest about the feel of a tune?",difficulty:0,choices:[{id:"a",text:"Two beats per bar, each divided into three eighth notes (jig feel)",correct:!0},{id:"b",text:"Six equal beats per bar, all stressed equally"},{id:"c",text:"Three quarter-note beats per bar (waltz feel)"},{id:"d",text:"Four beats per bar with a backbeat on two and four"}],explain:"6/8 is compound duple meter: two main beats per bar, each subdivided into three eighth notes, giving the lilt of a jig."},{id:"foundations-rhythm-01-q2",type:"mcq",prompt:"In 4/4 time, how many quarter-note beats are in one full bar?",difficulty:0,choices:[{id:"a",text:"4",correct:!0},{id:"b",text:"2"},{id:"c",text:"3"},{id:"d",text:"8"}],explain:"The top number of a simple time signature tells you how many beats of the given note value fit in one measure. 4/4 has four quarter-note beats."}]},{id:"foundations-accidentals-01",title:"Sharps, Flats, and Accidentals",track:"foundations",kind:"theory_lesson",difficulty:1,tags:["accidentals","pitch","keys"],prerequisites:["foundations-pitch-01"],estimateMinutes:4,body:"Accidentals raise or lower a pitch by a half step (semitone). A sharp (\u266f) raises a note; a flat (\u266d) lowers it; a natural (\u266e) cancels a previous sharp or flat for that note in the measure. On fretted instruments one fret equals one semitone, which makes accidentals easy to feel under your fingers.\n\nThe key signature at the start of a tune places sharps or flats on specific lines or spaces, and they apply to every occurrence of those letter names unless overridden by an accidental in the measure. F\u266f in the key signature means every F in the tune is sharp unless marked otherwise. This is why D major and G major feel different on the same melody: the collection of available pitches changes.\n\nAccidentals that appear mid-measure usually apply only until the end of that bar. Chromatic passing tones \u2014 notes that slide between scale degrees \u2014 are common in ornamented trad playing even when they are not written down. Reading key signatures accurately saves you from guessing whether a note is natural or altered.",tryThis:"",quizzes:[{id:"foundations-accidentals-01-q1",type:"mcq",prompt:"What effect does a sharp (\u266f) have on a note?",difficulty:1,choices:[{id:"a",text:"Raises the pitch by one semitone",correct:!0},{id:"b",text:"Lowers the pitch by one semitone"},{id:"c",text:"Raises the pitch by one whole tone"},{id:"d",text:"Cancels a previous accidental"}],explain:"A sharp raises a pitch by one half step (semitone), the same distance as one fret on guitar or one key on a piano."},{id:"foundations-accidentals-01-q2",type:"truefalse",prompt:"Notes in a key signature remain altered throughout the tune unless cancelled by a natural or a new accidental.",difficulty:1,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Key signature accidentals apply to every occurrence of that letter name in every octave, unless a natural sign or accidental overrides them in a measure."}]},{id:"scales-major-01",title:"Major Scales and the Leading Tone",track:"foundations",kind:"theory_lesson",difficulty:1,tags:["scales","major","leading-tone"],prerequisites:["foundations-accidentals-01"],estimateMinutes:5,body:"A major scale follows the interval pattern whole\u2013whole\u2013half\u2013whole\u2013whole\u2013whole\u2013half (WWHWWWH), measured between consecutive scale degrees. From C this yields C D E F G A B C with no sharps or flats. Transpose the same pattern to G and you need F\u266f; start on F and you need B\u266d. The pattern is fixed even when the letter names change.\n\nScale degree names help you talk about melody: the first note is the tonic (home base), the fifth is the dominant (strong anchor), and the seventh is the leading tone \u2014 a half step below the tonic that strongly pulls upward to resolve. That pull is why a major tune ending on the seventh feels unfinished until you reach the tonic.\n\nFor session players, knowing the major scale in the keys you play most (G, D, A, C, and their relatives) makes transposing and harmonising by ear much faster. The WWHWWWH formula is a reliable checklist when you are unsure which notes belong in an unfamiliar key.",tryThis:"",quizzes:[{id:"scales-major-01-q1",type:"mcq",prompt:"What is the interval pattern for a major scale?",difficulty:1,choices:[{id:"a",text:"WWHWWWH",correct:!0},{id:"b",text:"WHWWHWW"},{id:"c",text:"WWWHWWH"},{id:"d",text:"WHWWWHW"}],explain:"Major scales always follow whole\u2013whole\u2013half\u2013whole\u2013whole\u2013whole\u2013half between scale degrees, regardless of starting note."},{id:"scales-major-01-q2",type:"mcq",prompt:"In a major scale, the seventh scale degree is called the:",difficulty:1,choices:[{id:"a",text:"Leading tone",correct:!0},{id:"b",text:"Subdominant"},{id:"c",text:"Mediant"},{id:"d",text:"Supertonic"}],explain:"The seventh degree sits a half step below the tonic and tends to resolve upward, \u201cleading\u201d the ear back home."}]},{id:"scales-minor-01",title:"Natural, Harmonic, and Melodic Minor",track:"foundations",kind:"theory_lesson",difficulty:2,tags:["scales","minor","modes"],prerequisites:["scales-major-01"],estimateMinutes:5,body:"Minor keys share the tonic\u2013dominant relationship of major keys but use a different collection of pitches. The natural minor scale follows the pattern W-H-W-W-H-W-W from the tonic. A natural in A minor is A B C D E F G A \u2014 the relative minor of C major, using the same key signature.\n\nHarmonic minor raises the seventh degree by a half step, creating a strong leading tone (G\u266f in A harmonic minor). This scale is common in classical harmony and gives minor-key cadences their characteristic pull. Melodic minor raises both the sixth and seventh degrees ascending (A B C D E F\u266f G\u266f A) but often reverts to natural minor descending, smoothing out awkward augmented intervals in melody.\n\nTrad tunes in minor modes (A minor, E minor, D minor) frequently mix these flavours without labelling them. A piper might lean on the raised seventh in a closing phrase while keeping the lowered sixth elsewhere. Recognising the three minor variants helps you predict which accidentals may appear in a tune and why.",tryThis:"",quizzes:[{id:"scales-minor-01-q1",type:"mcq",prompt:"Which change defines harmonic minor compared to natural minor?",difficulty:2,choices:[{id:"a",text:"The seventh degree is raised by a semitone",correct:!0},{id:"b",text:"The third degree is lowered by a semitone"},{id:"c",text:"The fifth degree is raised by a semitone"},{id:"d",text:"All scale degrees are lowered"}],explain:"Harmonic minor raises only the seventh scale degree, creating a leading tone a half step below the tonic."},{id:"scales-minor-01-q2",type:"truefalse",prompt:"A natural minor has the same key signature as its relative major (three semitones higher).",difficulty:2,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Relative major and minor share a key signature: A minor is relative to C major, E minor to G major, and so on."}]},{id:"intervals-01",title:"Intervals: Measuring Distance Between Notes",track:"foundations",kind:"theory_lesson",difficulty:2,tags:["intervals","ear-training","harmony"],prerequisites:["scales-major-01"],estimateMinutes:5,body:"An interval is the distance between two pitches, named by counting letter names from the lower note to the higher (inclusive) and describing the quality (major, minor, perfect, augmented, or diminished). From C up to G is a fifth because you count C-D-E-F-G. C to E is a third; C to B is a seventh.\n\nPerfect intervals (unison, fourth, fifth, octave) have a stable, open sound. Major and minor thirds define the colour of chords: a major third sounds bright, a minor third darker. Seconds and sevenths tend to feel tense and often want to resolve. Learning to recognise thirds and fifths by ear is one of the highest-leverage skills for harmonising tunes at a session.\n\nIn ABC and printed scores, melodic intervals appear between consecutive notes; harmonic intervals sound simultaneously. Tuning matters: on fiddle, slightly narrowing major thirds compared to equal temperament is a long-standing practice. Interval names give you a shared vocabulary with other musicians when discussing harmony, transposition, and chord spelling.",tryThis:"",quizzes:[{id:"intervals-01-q1",type:"mcq",prompt:"From C up to E (C\u2013D\u2013E) is what kind of interval?",difficulty:2,choices:[{id:"a",text:"Major third",correct:!0},{id:"b",text:"Minor third"},{id:"c",text:"Perfect fourth"},{id:"d",text:"Major second"}],explain:"Counting letter names C-D-E gives a third; in the major scale C to E spans two whole steps, making it a major third."},{id:"intervals-01-q2",type:"mcq",prompt:"Which intervals are called \u201cperfect\u201d in traditional Western theory?",difficulty:2,choices:[{id:"a",text:"Unison, fourth, fifth, and octave",correct:!0},{id:"b",text:"Major and minor thirds only"},{id:"c",text:"All seconds and sevenths"},{id:"d",text:"Only the octave"}],explain:"Perfect intervals \u2014 unison, fourth, fifth, and octave \u2014 have a characteristic stable quality distinct from major/minor thirds and sixths."}]},{id:"keys-circle-01",title:"The Circle of Fifths and Key Signatures",track:"foundations",kind:"theory_lesson",difficulty:3,tags:["keys","circle-of-fifths","signatures"],prerequisites:["scales-major-01","foundations-accidentals-01"],estimateMinutes:6,body:"The circle of fifths arranges keys so each step clockwise adds one sharp. Starting at C (no sharps or flats), G major has one sharp, D major two, A major three, and so on. Moving counter-clockwise adds flats: F major has one flat, B\u266d major two, E\u266d major three. Keys a fifth apart share six of seven scale degrees, which is why modulations often move by fifths.\n\nThe order of sharps in key signatures is F\u266f C\u266f G\u266f D\u266f A\u266f E\u266f B\u266f \u2014 remembered by the mnemonic \u201cFather Charles Goes Down And Ends Battle.\u201d Flats appear in the reverse order: B\u266d E\u266d A\u266d D\u266d G\u266d C\u266d F\u266d (\u201cBattle Ends And Down Goes Charles\u2019 Father\u201d). The last sharp in a key signature tells you the major key: for sharps, go up a half step from that sharp; for flats, the second-to-last flat names the major key.\n\nFor trad musicians, the sharp-side keys G, D, A, and E dominate fiddle and whistle repertoire, while B\u266d and F appear often on flute and box. Mapping tunes onto the circle reveals friendly modulations and helps you prepare accidentals before the first downbeat.",tryThis:"",quizzes:[{id:"keys-circle-01-q1",type:"mcq",prompt:"What is the correct order of sharps added in key signatures?",difficulty:3,choices:[{id:"a",text:"F\u266f C\u266f G\u266f D\u266f A\u266f E\u266f B\u266f",correct:!0},{id:"b",text:"G\u266f D\u266f A\u266f E\u266f B\u266f F\u266f C\u266f"},{id:"c",text:"C\u266f G\u266f D\u266f A\u266f E\u266f B\u266f F\u266f"},{id:"d",text:"F\u266f G\u266f A\u266f B\u266f C\u266f D\u266f E\u266f"}],explain:"Sharps always enter key signatures in the fixed order F-C-G-D-A-E-B, moving by fifths."},{id:"keys-circle-01-q2",type:"mcq",prompt:"How many sharps are in the key of D major?",difficulty:3,choices:[{id:"a",text:"2 (F\u266f and C\u266f)",correct:!0},{id:"b",text:"1 (F\u266f only)"},{id:"c",text:"3 (F\u266f, C\u266f, and G\u266f)"},{id:"d",text:"None"}],explain:"D major is two steps clockwise from C on the circle of fifths, so it carries F\u266f and C\u266f in its key signature."}]}]).concat([{id:"italian-tempo-01",title:"Italian Tempo Markings",track:"italian",kind:"theory_lesson",difficulty:1,tags:["tempo","italian","performance"],prerequisites:[],estimateMinutes:4,body:"Italian tempo markings appear on printed scores and in tune collections to suggest how fast a piece should feel. They describe character as much as speed: Allegro means lively and fast, Andante means walking pace, Adagio means slow and stately, and Presto means very fast. Moderato sits in the middle \u2014 neither rushed nor dragging.\n\nMany markings modify a base tempo. Allegretto is a little slower than allegro; Andantino can be slightly faster than andante depending on period and editor. Largo and Lento both indicate slow tempi, but largo often implies broad, open phrases. Vivace adds sparkle and energy beyond mere speed.\n\nIn trad sessions tempo is usually negotiated by the leader\u2019s first phrase rather than a printed marking, but these terms still appear on classical arrangements, c\xe9il\xed band charts, and written-out sets. Recognising them helps you interpret recordings and printed versions of tunes that were originally passed down by ear.",tryThis:"",quizzes:[{id:"italian-tempo-01-q1",type:"mcq",prompt:"Which tempo marking suggests a walking pace?",difficulty:1,choices:[{id:"a",text:"Andante",correct:!0},{id:"b",text:"Presto"},{id:"c",text:"Allegro"},{id:"d",text:"Vivace"}],explain:"Andante literally means \u201cwalking\u201d and indicates a moderate, steady tempo slower than allegro."},{id:"italian-tempo-01-q2",type:"mcq",prompt:"Which marking indicates a very fast tempo?",difficulty:1,choices:[{id:"a",text:"Presto",correct:!0},{id:"b",text:"Largo"},{id:"c",text:"Adagio"},{id:"d",text:"Andante"}],explain:"Presto is among the fastest common tempo indications, faster than allegro and vivace in most classical usage."}]},{id:"italian-dynamics-01",title:"Dynamic Markings: From Pianissimo to Fortissimo",track:"italian",kind:"theory_lesson",difficulty:1,tags:["dynamics","italian","expression"],prerequisites:[],estimateMinutes:4,body:"Dynamic markings tell performers how loud or soft to play. Piano (p) means soft; forte (f) means loud. Doubling the letter intensifies the effect: pianissimo (pp) is very soft, fortissimo (ff) very loud. Mezzo (m) means \u201cmoderately\u201d: mezzo piano (mp) is moderately soft, mezzo forte (mf) is moderately loud \u2014 often the default speaking volume in ensemble playing.\n\nCrescendo (gradually louder) and diminuendo or decrescendo (gradually softer) shape phrases over several bars. A sudden accent is marked sf or sfz (sforzando). In trad music, dynamics are rarely written note-for-note, but good players still breathe crescendi into long notes and lighten repeated figures to avoid monotony.\n\nDynamics interact with articulation and tempo: a reel played mf with crisp bowing feels different from the same tune played mp with more sustain. When arranging for c\xe9il\xed band or session recording, marking a few strategic dynamic changes can clarify tune changes and set off solo passages.",tryThis:"",quizzes:[{id:"italian-dynamics-01-q1",type:"mcq",prompt:"What does \u201cmf\u201d stand for?",difficulty:1,choices:[{id:"a",text:"Mezzo forte (moderately loud)",correct:!0},{id:"b",text:"Molto forte (very loud)"},{id:"c",text:"Mezzo piano (moderately soft)"},{id:"d",text:"Minor fortissimo"}],explain:"mf means mezzo forte \u2014 moderately loud, a common default dynamic in ensemble and solo playing."},{id:"italian-dynamics-01-q2",type:"truefalse",prompt:"A crescendo marking means to gradually get louder.",difficulty:1,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Crescendo (often abbreviated cresc.) indicates a steady increase in volume over the marked passage."}]},{id:"italian-articulation-01",title:"Articulation Marks: Legato, Staccato, and Accents",track:"italian",kind:"theory_lesson",difficulty:2,tags:["articulation","italian","technique"],prerequisites:[],estimateMinutes:4,body:"Articulation marks describe how notes connect or separate. Legato means smooth and connected; staccato means detached, with space between notes. A slur curves over notes that should be played in one breath or bow stroke without re-articulating each pitch. A dot above or below a notehead also indicates staccato in many styles.\n\nAccents (>) stress individual notes within a phrase. Tenuto (\u2014) asks for full value and slight emphasis. Marcato suggests a marked, emphatic attack. Trills, mordents, and turns are ornament signs common in classical sources and some baroque-influenced trad settings, though Irish ornamentation is often learned by ear rather than from symbols.\n\nFor string players, articulation is largely bowing: same-note re-bowing versus slurring changes the dance feel of a reel entirely. Wind players use tonguing patterns (doo-doo vs doo-goo). Matching articulation to dance type \u2014 crisp for reels, slightly more legato for airs \u2014 is as important as playing the right notes.",tryThis:"",quizzes:[{id:"italian-articulation-01-q1",type:"mcq",prompt:"What does \u201clegato\u201d mean?",difficulty:2,choices:[{id:"a",text:"Smooth and connected",correct:!0},{id:"b",text:"Short and detached"},{id:"c",text:"Very loud"},{id:"d",text:"Gradually slower"}],explain:"Legato indicates that notes should flow into one another without noticeable gaps between attacks."},{id:"italian-articulation-01-q2",type:"mcq",prompt:"A slur marking over several notes indicates:",difficulty:2,choices:[{id:"a",text:"Play the notes in one connected gesture without re-articulating each one",correct:!0},{id:"b",text:"Play each note with a heavy accent"},{id:"c",text:"Repeat the notes in a loop"},{id:"d",text:"Play the passage an octave higher"}],explain:"A slur connects the covered notes into a single phrase, using one bow stroke, breath, or tonguing pattern."}]},{id:"italian-form-01",title:"Form Labels: D.C., D.S., Coda, and Fine",track:"italian",kind:"theory_lesson",difficulty:2,tags:["form","italian","notation"],prerequisites:[],estimateMinutes:5,body:"Italian form directions tell you how to navigate repeats and endings in longer pieces. Da capo (D.C.) means \u201cfrom the head\u201d \u2014 return to the beginning. Da capo al fine means play from the start until you reach fine (\u201cend\u201d). Dal segno (D.S.) means \u201cfrom the sign\u201d (the segno symbol), often skipping an opening section on the repeat.\n\nCoda designates a concluding section reached only after a jump marked \u201cTo Coda\u201d or via a D.S. al coda instruction. Understanding these signs prevents you from stopping too early in a set piece or classical arrangement of a trad tune. In simpler dance tunes, first and second endings (1. / 2.) accomplish a similar job with less Italian vocabulary.\n\nMany session tunes use AABB or AB form without written navigation signs, but printed collections of O\u2019Carolan pieces, hornpipe variants, and c\xe9il\xed set arrangements routinely include D.C. and D.S. markings. Reading them confidently keeps you aligned with the rest of the ensemble on the repeat.",tryThis:"",quizzes:[{id:"italian-form-01-q1",type:"mcq",prompt:"What does \u201cD.C. al fine\u201d mean?",difficulty:2,choices:[{id:"a",text:"Return to the beginning and play until you reach \u201cfine\u201d",correct:!0},{id:"b",text:"Skip to the coda immediately"},{id:"c",text:"Play the second ending only"},{id:"d",text:"Repeat the last four bars"}],explain:"Da capo al fine sends the performer back to the start (capo) and forward until the marking fine, then stop."},{id:"italian-form-01-q2",type:"truefalse",prompt:"\u201cD.S.\u201d means to resume playing from the segno sign, not from the very beginning.",difficulty:2,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Dal segno directs the player to the segno symbol placed earlier in the score, skipping material before that point on the repeat."}]}]).concat([{id:"chords-triads-01",title:"Triads: Major, Minor, Diminished, and Augmented",track:"chords",kind:"theory_lesson",difficulty:2,tags:["triads","harmony","chords"],prerequisites:["intervals-01"],estimateMinutes:5,body:"A triad is a three-note chord built by stacking thirds above a root. A major triad has a major third below a minor third (root\u2013major 3rd\u2013perfect 5th): C\u2013E\u2013G. A minor triad flips the first third to minor (root\u2013minor 3rd\u2013perfect 5th): A\u2013C\u2013E. These two qualities cover most accompaniment in folk and trad music.\n\nDiminished triads use two minor thirds (root\u2013minor 3rd\u2013diminished 5th) and sound tense and unstable. Augmented triads use two major thirds (root\u2013major 3rd\u2013augmented 5th) and appear less often but colour certain passing harmonies. On guitar or piano, knowing triad shapes in the keys you play lets you comp behind a melody without reading full scores.\n\nRoman numerals often label triads by scale degree: I is major in major keys, ii minor, iii minor, IV major, V major, vi minor, vii\xb0 diminished. Matching a tune\u2019s home key to its diatonic triads is the first step toward playing useful session backup.",tryThis:"",quizzes:[{id:"chords-triads-01-q1",type:"mcq",prompt:"Which notes form a C major triad?",difficulty:2,choices:[{id:"a",text:"C\u2013E\u2013G",correct:!0},{id:"b",text:"C\u2013E\u266d\u2013G"},{id:"c",text:"C\u2013F\u2013A"},{id:"d",text:"C\u2013D\u2013G"}],explain:"A major triad stacks a major third (C\u2013E) and a minor third (E\u2013G) above the root C."},{id:"chords-triads-01-q2",type:"mcq",prompt:"A minor triad differs from a major triad because its:",difficulty:2,choices:[{id:"a",text:"Third above the root is a semitone smaller",correct:!0},{id:"b",text:"Fifth above the root is always diminished"},{id:"c",text:"Root is lowered by a semitone"},{id:"d",text:"Third and fifth are both major"}],explain:"Minor triads have a minor third above the root (three semitones) instead of a major third (four semitones)."}]},{id:"chords-inversions-01",title:"Triad Inversions and Bass Notes",track:"chords",kind:"theory_lesson",difficulty:3,tags:["inversions","bass","chords"],prerequisites:["chords-triads-01"],estimateMinutes:5,body:"A triad in root position places the root in the bass (C\u2013E\u2013G for C major). First inversion puts the third in the bass (E\u2013G\u2013C), often written C/E. Second inversion puts the fifth in the bass (G\u2013C\u2013E), written C/G. The chord symbol stays the same because the pitch class collection is unchanged \u2014 only the lowest note moves.\n\nInversions affect voice leading and bass motion. A descending bass line C\u2013B\u2013A\u2013G might use C, G/B, Am, G/C shapes on guitar or keyboard. Inversions also change which melody notes sit on top, helping accompanists avoid clashing with a fiddle line. Figured-bass numbers (6 for first inversion, 6/4 for second) appear in classical sources but modern chord charts use slash notation.\n\nTrad accompanists often choose inversions by ear to keep the right hand or picking pattern close to the previous chord shape. Smooth bass motion makes sets feel cohesive even when the harmonic rhythm is simple I\u2013V\u2013I patterns.",tryThis:"",quizzes:[{id:"chords-inversions-01-q1",type:"mcq",prompt:"C/E (C with E in the bass) is which inversion of C major?",difficulty:3,choices:[{id:"a",text:"First inversion",correct:!0},{id:"b",text:"Root position"},{id:"c",text:"Second inversion"},{id:"d",text:"Not an inversion of C major"}],explain:"When the third of the triad (E in C major) is the lowest note, the chord is in first inversion."},{id:"chords-inversions-01-q2",type:"truefalse",prompt:"A chord inversion changes the chord\u2019s letter name (e.g., C major stays C major).",difficulty:3,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Inversions rearrange the same three pitch classes; the root and chord quality determine the symbol, while slash notation shows the bass note."}]},{id:"chords-sevenths-01",title:"Seventh Chords and Their Qualities",track:"chords",kind:"theory_lesson",difficulty:4,tags:["sevenths","jazz","harmony"],prerequisites:["chords-triads-01"],estimateMinutes:5,body:"Adding a seventh above the root creates richer four-note chords. A major seventh (maj7) stacks a major triad with a major seventh: C\u2013E\u2013G\u2013B. A dominant seventh (7) uses a minor seventh above the root: C\u2013E\u2013G\u2013B\u266d \u2014 the V7 chord that strongly pulls to I in major keys. A minor seventh (m7) combines a minor triad with a minor seventh: D\u2013F\u2013A\u2013C.\n\nHalf-diminished (m7\u266d5) and fully diminished (dim7) sevenths appear in minor-key harmony and jazz turnarounds. In trad contexts, plain dominant sevenths colour c\xe9il\xed band voicings and American-influenced folk songs; maj7 chords appear more in contemporary arrangements than in strict Irish session backup.\n\nRecognising seventh-chord quality by ear helps you choose substitute shapes on guitar or accordion. The third and seventh of a chord (the \u201cguide tones\u201d) define its function even when the root is omitted in a dense mix.",tryThis:"",quizzes:[{id:"chords-sevenths-01-q1",type:"mcq",prompt:"A G7 chord contains which seventh above G?",difficulty:4,choices:[{id:"a",text:"F (minor seventh)",correct:!0},{id:"b",text:"F\u266f (major seventh)"},{id:"c",text:"E (minor seventh)"},{id:"d",text:"A (major ninth)"}],explain:"Dominant seventh chords use a minor seventh interval above the root: G to F is ten semitones (a minor seventh)."},{id:"chords-sevenths-01-q2",type:"mcq",prompt:"Which seventh chord type is built on the fifth degree of a major key and pulls strongly to I?",difficulty:4,choices:[{id:"a",text:"Dominant seventh (V7)",correct:!0},{id:"b",text:"Major seventh (Imaj7)"},{id:"c",text:"Minor seventh (ii7)"},{id:"d",text:"Fully diminished seventh (vii\xb07)"}],explain:"The dominant seventh chord on scale degree 5 contains the leading tone tendency and tritone that resolve to the tonic."}]},{id:"chords-diatonic-major-01",title:"Diatonic Triads in Major Keys",track:"chords",kind:"theory_lesson",difficulty:3,tags:["diatonic","major","roman-numerals"],prerequisites:["chords-triads-01","scales-major-01"],estimateMinutes:5,body:"Diatonic triads are built on each degree of the major scale using only notes from that scale. In G major the pattern is: I (G), ii (Am), iii (Bm), IV (C), V (D), vi (Em), vii\xb0 (F\u266fdim). Capital numerals mean major; lowercase mean minor; \xb0 marks diminished.\n\nThe I, IV, and V chords are primary harmonies in countless folk songs and dance tunes. vi (relative minor) is nearly as common \u2014 think of the emotional shift in songs that move between I and vi. ii often precedes V in slightly more sophisticated progressions. vii\xb0 is rare in bare trad backup but appears in classical arrangements.\n\nWhen guessing chords for a tune in D major, start with D, G, A, and Bm. If the melody emphasises B and D over an F\u266f in the bass, you may be on the V chord. Mapping melody notes to chord tones is a practical session skill that grows directly from this diatonic chart.",tryThis:"",quizzes:[{id:"chords-diatonic-major-01-q1",type:"mcq",prompt:"In the key of G major, what is the vi chord?",difficulty:3,choices:[{id:"a",text:"Em",correct:!0},{id:"b",text:"Am"},{id:"c",text:"Bm"},{id:"d",text:"C"}],explain:"vi is built on the sixth scale degree: in G major that is E, forming an E minor triad (E\u2013G\u2013B)."},{id:"chords-diatonic-major-01-q2",type:"mcq",prompt:"Which Roman numeral pattern describes triads in a major key?",difficulty:3,choices:[{id:"a",text:"I ii iii IV V vi vii\xb0",correct:!0},{id:"b",text:"I II III IV V VI VII (all major)"},{id:"c",text:"i ii\xb0 III iv v VI VII"},{id:"d",text:"I iv V VI (no minor chords)"}],explain:"Major-key diatonic triads follow major-minor-minor-major-major-minor-diminished on degrees 1 through 7."}]},{id:"chords-diatonic-minor-01",title:"Diatonic Harmony in Minor Keys",track:"chords",kind:"theory_lesson",difficulty:4,tags:["diatonic","minor","harmony"],prerequisites:["scales-minor-01","chords-diatonic-major-01"],estimateMinutes:5,body:"Minor-key harmony draws on natural, harmonic, and melodic minor scales, so the available chords shift more than in major. In A natural minor: i (Am), ii\xb0 (Bdim), III (C), iv (Dm), v (Em), VI (F), VII (G). Harmonic minor raises the seventh degree, making V a major chord (E major in A minor) with a strong pull to i.\n\nThe raised seventh is why minor-key tunes often end with E\u2192Am rather than Em\u2192Am in A minor. III and VI (C and F in A minor) are common modal-flavoured pivots in folk melody. VII (G major) can feel mixolydian when emphasised over an A drone.\n\nAccompanists in minor keys should listen for whether the tune uses the raised seventh in cadences. Irish and Scottish minor-mode tunes often blend aeolian and dorian flavours without announcing which textbook scale they follow.",tryThis:"",quizzes:[{id:"chords-diatonic-minor-01-q1",type:"mcq",prompt:"In A harmonic minor, what quality is the V chord?",difficulty:4,choices:[{id:"a",text:"E major",correct:!0},{id:"b",text:"E minor"},{id:"c",text:"Em7"},{id:"d",text:"E diminished"}],explain:"Harmonic minor raises the seventh degree (G\u266f in A minor), making the fifth-degree triad major: E\u2013G\u266f\u2013B."},{id:"chords-diatonic-minor-01-q2",type:"truefalse",prompt:"In natural minor, the triad on scale degree ii is diminished.",difficulty:4,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Built on the second degree of natural minor, the ii chord stacks two minor thirds, yielding a diminished triad."}]},{id:"chords-extensions-01",title:"Chord Extensions: 9ths, 11ths, and 13ths",track:"chords",kind:"theory_lesson",difficulty:6,tags:["extensions","jazz","voicing"],prerequisites:["chords-sevenths-01"],estimateMinutes:6,body:"Extensions add colour tones above the seventh by continuing to stack thirds. A ninth is the second an octave up; an eleventh the fourth; a thirteenth the sixth. In practice, players omit some chord tones to keep voicings playable \u2014 a G13 chord might be voiced G\u2013F\u2013E\u2013B (root, 7th, 13th, 3rd) without every extension sounding at once.\n\nChord symbols like Cmaj9, Dm11, or G13 tell you which extensions belong to the harmony. Major chords often take major 9ths; dominant chords accept altered tensions (\u266d9, \u266f11) in jazz but rarely in trad backup. Extensions clarify colour when the bass and melody already state the core function.\n\nFor folk musicians exploring jazz-adjacent arranging, add extensions one at a time: try a maj7 before maj9, or a plain 7 before 9. Listen for whether the added tone supports the melody or fights it. Space and register matter more than spelling every extension on paper.",tryThis:"",quizzes:[{id:"chords-extensions-01-q1",type:"mcq",prompt:"A chord labeled \u201cmaj9\u201d includes which interval above the root (in addition to the major 7th)?",difficulty:6,choices:[{id:"a",text:"Major ninth (compound major second)",correct:!0},{id:"b",text:"Minor ninth only"},{id:"c",text:"Perfect eleventh without a seventh"},{id:"d",text:"Augmented fourth only"}],explain:"The 9 in maj9 indicates a major ninth above the root \u2014 the major second displaced by an octave \u2014 stacked above the maj7 chord."},{id:"chords-extensions-01-q2",type:"truefalse",prompt:"In real-world voicings, players often omit some chord tones when adding extensions.",difficulty:6,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Practical voicings on guitar and piano frequently drop the fifth or even root, keeping guide tones and selected extensions within hand span."}]},{id:"chords-jazz-color-01",title:"Altered Dominants and Jazz Colour Chords",track:"chords",kind:"theory_lesson",difficulty:8,tags:["jazz","altered","dominant"],prerequisites:["chords-extensions-01","chords-sevenths-01"],estimateMinutes:7,body:"Altered dominant chords intensify the pull toward a target by sharpening or flattening extensions on a V7 chord. G7(\u266d9) or G7(\u266f5) heighten tension before resolving to C major or C minor. The altered scale (also called super locrian) matches many of these tensions and is a staple of jazz improvisation.\n\nTritone substitution replaces V7 with a dominant chord a tritone away (Db7 for G7) because the two chords share the same guide tones (F and B/Cb). Secondary dominants temporarily tonicise another scale degree: A7\u2192Dm in the key of C is V7/vi. These devices appear in jazz standards and in modern folk-jazz crossover arranging.\n\nTrad players need not master every altered voicing, but recognising when a chart asks for G7\u266f9 versus plain G7 prevents wrong notes in fusion settings. When in doubt, play the third and seventh clearly and let the soloist supply altered tensions.",tryThis:"",quizzes:[{id:"chords-jazz-color-01-q1",type:"mcq",prompt:"Which chord is a common tritone substitution for G7 in the key of C?",difficulty:8,choices:[{id:"a",text:"D\u266d7",correct:!0},{id:"b",text:"D7"},{id:"c",text:"B\u266d7"},{id:"d",text:"A7"}],explain:"D\u266d7 is a tritone away from G7 and shares the same tritone interval (B\u2013F), allowing it to resolve similarly to C."},{id:"chords-jazz-color-01-q2",type:"mcq",prompt:"An \u201caltered dominant\u201d typically modifies:",difficulty:8,choices:[{id:"a",text:"The fifth and/or ninth (and related extensions) of a V7 chord",correct:!0},{id:"b",text:"Only the root of a I chord"},{id:"c",text:"The third of a minor triad to major"},{id:"d",text:"The octave doubling of the bass line"}],explain:"Altered dominants sharpen or flatten the fifth and ninth (and sometimes other extensions) to increase harmonic tension before resolution."}]}]).concat([{id:"transpose-why-01",title:"Why Transpose? Keys, Instruments, and Voices",track:"transposition",kind:"theory_lesson",difficulty:2,tags:["transposition","keys","instruments"],prerequisites:["keys-circle-01"],estimateMinutes:4,body:"Transposition means moving a whole piece \u2014 melody and harmony \u2014 up or down by a fixed interval so it sounds in a different key. Players transpose to fit their instrument\u2019s comfortable range, to match a singer\u2019s voice, or to align with another musician who knows a tune only in D when the session is in G.\n\nSome instruments are transposing by convention: B\u266d clarinet and trumpet parts are written so that when the player reads C, the concert pitch is B\u266d. Whistle and accordion players often think in written fingerings rather than concert pitch. Understanding whether you are talking about written or concert pitch prevents confusion at workshops and band rehearsals.\n\nTransposing does not change the tune\u2019s internal relationships: intervals, contour, and harmonic functions stay the same. Only the absolute pitch shifts. That is why a reel learned in A can move to G without rewriting the melody\u2019s shape \u2014 you are relocating the same pattern on the fingerboard or keyboard.",tryThis:"",quizzes:[{id:"transpose-why-01-q1",type:"mcq",prompt:"What stays the same when you transpose a tune to a new key?",difficulty:2,choices:[{id:"a",text:"The intervals and melodic shape",correct:!0},{id:"b",text:"The absolute concert pitch of every note"},{id:"c",text:"The key signature only, not the notes"},{id:"d",text:"The time signature and bar count only"}],explain:"Transposition shifts all pitches equally, preserving intervals, contour, and harmonic relationships."},{id:"transpose-why-01-q2",type:"truefalse",prompt:"Players often transpose to match a singer\u2019s comfortable range.",difficulty:2,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Vocal range is a primary reason to move a song to a higher or lower key so the melody sits comfortably for the singer."}]},{id:"transpose-melody-01",title:"Transposing Melodies by Interval",track:"transposition",kind:"theory_lesson",difficulty:3,tags:["melody","intervals","transposition"],prerequisites:["transpose-why-01","intervals-01"],estimateMinutes:5,body:"To transpose a melody, move every note by the same interval \u2014 up a tone from D to E major, down a perfect fourth from G to D, and so on. If the tune starts on D and you transpose up a whole step, every D becomes E, every F\u266f becomes G\u266f, and the key signature gains two sharps instead of one.\n\nScale-degree thinking speeds this up: if the opening phrase begins on the fifth degree of G major (D), the same phrase in D major begins on A, the fifth of D. Many trad players transpose by interval on the fly rather than rewriting ABC, especially when switching whistle keys mid-set.\n\nAccidentals in the original must move with their notes. A C\u266e in F major becomes D\u266e when you transpose up a whole step to G major \u2014 not C\u266f unless the harmonic context demands it. Checking the first and last notes plus the highest peak often confirms you landed in the right key.",tryThis:"",quizzes:[{id:"transpose-melody-01-q1",type:"mcq",prompt:"Transposing a tune from G major up a major second lands in which key?",difficulty:3,choices:[{id:"a",text:"A major",correct:!0},{id:"b",text:"D major"},{id:"c",text:"F major"},{id:"d",text:"E minor only (never major)"}],explain:"A major second (whole step) above G is A; the key signature adds one sharp (G major has F\u266f, A major adds C\u266f)."},{id:"transpose-melody-01-q2",type:"mcq",prompt:"When transposing by interval, you should:",difficulty:3,choices:[{id:"a",text:"Move every note (including accidentals) by the same interval",correct:!0},{id:"b",text:"Move only the first note of each bar"},{id:"c",text:"Change the rhythm but keep pitch names"},{id:"d",text:"Transpose only notes on strong beats"}],explain:"Consistent interval shift preserves the melody; selective moves would distort intervals and harmony."}]},{id:"transpose-chords-01",title:"Transposing Chord Progressions",track:"transposition",kind:"theory_lesson",difficulty:4,tags:["chords","transposition","Nashville"],prerequisites:["transpose-melody-01","chords-diatonic-major-01"],estimateMinutes:5,body:"Chord progressions transpose by moving every chord symbol the same distance. A I\u2013V\u2013vi\u2013IV loop in G (G\u2013D\u2013Em\u2013C) becomes A\u2013E\u2013F\u266fm\u2013D in A when moved up a whole step. Roman numerals describe the functions, so the same chart works in any major key once you know the local I, IV, V, and vi triads.\n\nNashville Number System labels chords 1\u20137 by scale degree, independent of letter names. \u201c1\u20135\u20136m\u20134\u201d in D is D\u2013A\u2013Bm\u2013G; in G it is G\u2013D\u2013Em\u2013C. Session guitarists often call changes by number when a singer requests a new key between verses.\n\nWatch for chords that are not diatonic: a borrowed \u266dVII or secondary dominant moves with the same interval as diatonic chords. Slash chords (G/B) transpose by shifting both the harmony and the bass note. Capo players mentally transpose: shapes in C with capo 2 sound in D.",tryThis:"",quizzes:[{id:"transpose-chords-01-q1",type:"mcq",prompt:"I\u2013V\u2013vi\u2013IV in the key of C is C\u2013G\u2013Am\u2013F. What is the same progression in G major?",difficulty:4,choices:[{id:"a",text:"G\u2013D\u2013Em\u2013C",correct:!0},{id:"b",text:"G\u2013C\u2013D\u2013Em"},{id:"c",text:"G\u2013A\u2013Bm\u2013D"},{id:"d",text:"Em\u2013C\u2013G\u2013D"}],explain:"Each Roman numeral maps to its scale degree: I=G, V=D, vi=Em, IV=C in G major."},{id:"transpose-chords-01-q2",type:"truefalse",prompt:"The Nashville Number System labels chords by scale degree rather than letter name.",difficulty:4,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Numbers 1\u20137 represent chord roots by major-scale degree, making transposition a matter of mapping to the new key."}]},{id:"transpose-capo-01",title:"Capo Logic for Guitar and Mandolin",track:"transposition",kind:"theory_lesson",difficulty:3,tags:["capo","guitar","practical"],prerequisites:["transpose-chords-01"],estimateMinutes:4,body:"A capo shortens the vibrating string length, raising pitch without changing chord shapes. If you play G\u2013C\u2013D shapes with capo on the second fret, the sounding key is A major \u2014 each chord name moves up a whole step. Capo 3 from G shapes sounds B\u266d; capo 5 from G sounds C.\n\nCapo choice balances open-string resonance against vocal range. Folk guitarists often prefer familiar open chords (C, G, D, Em, Am) and capo to match the singer. Partial capos and cut capos create alternate tunings without retuning all strings, useful for drone effects in accompaniment.\n\nRemember: chord diagrams show finger shapes; the sounding key is shapes plus capo fret. Tell the band \u201ccapo 2, playing G shapes in A\u201d to avoid mismatch with concert-pitch instruments. ABC and printed scores are usually in concert pitch unless marked otherwise.",tryThis:"",quizzes:[{id:"transpose-capo-01-q1",type:"mcq",prompt:"G-major chord shapes with a capo on fret 2 sound in which key?",difficulty:3,choices:[{id:"a",text:"A major",correct:!0},{id:"b",text:"G major (unchanged)"},{id:"c",text:"B major"},{id:"d",text:"E major"}],explain:"Each fret raises pitch by a semitone; two frets (capo 2) raise G shapes by a whole step to A."},{id:"transpose-capo-01-q2",type:"mcq",prompt:"Why do guitarists use a capo instead of only barre chords?",difficulty:3,choices:[{id:"a",text:"To keep open-chord resonance and easier fingerings in a higher key",correct:!0},{id:"b",text:"To lower the pitch below standard tuning"},{id:"c",text:"To change the time signature"},{id:"d",text:"To mute all strings permanently"}],explain:"Capo lets players use comfortable open voicings while sounding in a higher concert key suited to voice or ensemble."}]},{id:"transpose-modes-01",title:"Modes and Modal Transposition",track:"transposition",kind:"theory_lesson",difficulty:7,tags:["modes","dorian","mixolydian"],prerequisites:["scales-major-01","transpose-melody-01"],estimateMinutes:6,body:"Modes are scales built by starting on different degrees of the major scale. D dorian (D E F G A B C D) shares the key signature of C major but centres on D. G mixolydian (G A B C D E F G) shares C major\u2019s signature but centres on G with a lowered seventh (F instead of F\u266f).\n\nModal thinking helps explain tunes that seem \u201cin major\u201d but avoid leading-tone cadences. Many Irish melodies in D mixolydian use C natural against a D centre; A dorian tunes use G natural in a context that feels like A minor with a major IV chord. Transposing modally means preserving which scale degrees are altered, not just shifting letter names.\n\nWhen moving a modal tune to a new key, keep the same intervallic colour: dorian keeps major 6th and minor 3rd relative to the tonic; mixolydian keeps minor 7th and major 3rd. Session players often describe these as \u201cD with a flat C\u201d rather than naming the mode, but the theory clarifies why certain accidentals persist across transpositions.",tryThis:"",quizzes:[{id:"transpose-modes-01-q1",type:"mcq",prompt:"D dorian has the same key signature as which major key?",difficulty:7,choices:[{id:"a",text:"C major (no sharps or flats)",correct:!0},{id:"b",text:"D major (two sharps)"},{id:"c",text:"F major (one flat)"},{id:"d",text:"G major (one sharp)"}],explain:"Dorian on D uses the white-key collection starting on D, matching C major\u2019s key signature."},{id:"transpose-modes-01-q2",type:"mcq",prompt:"Which scale degree is lowered in mixolydian compared to major?",difficulty:7,choices:[{id:"a",text:"Seventh (minor seventh above tonic)",correct:!0},{id:"b",text:"Third (making it minor)"},{id:"c",text:"Fourth (making it augmented)"},{id:"d",text:"Fifth (making it diminished)"}],explain:"Mixolydian differs from major by a lowered seventh scale degree, giving a dominant-seventh colour on the tonic chord."}]}]).concat([{id:"harmony-tendency-01",title:"Tendency Tones and Resolution",track:"harmony",kind:"theory_lesson",difficulty:4,tags:["tendency","resolution","voice-leading"],prerequisites:["chords-diatonic-major-01"],estimateMinutes:5,body:"Certain pitches in a key \u201cwant\u201d to move to others. The leading tone (seventh scale degree in major) rises to the tonic. The fourth degree in a V chord often falls to the third of I. These tendency tones create the feeling of arrival when a phrase ends.\n\nDominant harmony concentrates tension: the tritone between the third and seventh of V7 (B and F in G7\u2192C) resolves outward to C and E. Melodic tendency works too: a phrase ending on 2\u0302 often steps down to 1\u0302 or up to 3\u0302 depending on style. Trad players exploit this instinctively when ornamenting cadences.\n\nBacking musicians who land on chord tones that clash with unresolved melody tendency can sound \u201cwrong\u201d even when the chord is diatonic. Listening for where the melody wants to go helps you choose inversions and passing chords that support rather than block the line.",tryThis:"",quizzes:[{id:"harmony-tendency-01-q1",type:"mcq",prompt:"In major keys, the leading tone most strongly resolves:",difficulty:4,choices:[{id:"a",text:"Up to the tonic (by semitone)",correct:!0},{id:"b",text:"Down to the subdominant"},{id:"c",text:"Up to the mediant by whole tone"},{id:"d",text:"It has no preferred direction"}],explain:"The leading tone sits a half step below the tonic and conventionally rises to complete the cadence."},{id:"harmony-tendency-01-q2",type:"truefalse",prompt:"The tritone in a dominant seventh chord creates tension that typically resolves in a cadence.",difficulty:4,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"The augmented fourth/diminished fifth inside V7 resolves to stable chord tones of I, defining the dominant function."}]},{id:"harmony-voiceleading-01",title:"Voice Leading Basics",track:"harmony",kind:"theory_lesson",difficulty:5,tags:["voice-leading","part-writing","smoothness"],prerequisites:["harmony-tendency-01","chords-inversions-01"],estimateMinutes:6,body:"Voice leading describes how individual parts move from chord to chord. Smooth voice leading favours small steps, common tones held between chords, and contrary motion between outer voices. Large leaps in inner voices are fine on fiddle; in four-part harmony they can sound disjointed unless prepared.\n\nParallel perfect fifths and octaves between independent voices were avoided in classical part-writing because they weaken independence of lines. In trad ensemble playing the \u201cvoices\u201d might be fiddle, flute, and guitar \u2014 doubling the melody in octaves is normal, but two harmony instruments moving in parallel fifths throughout can hollow out the texture.\n\nPractical session voice leading: keep the bass moving by step or fifth when possible; let harmony instruments stick to chord tones on strong beats; add passing motion on weak beats. When arranging a three-part hornpipe set, assign one player roots, another thirds, another fifths or melody doubles \u2014 clarity beats cleverness.",tryThis:"",quizzes:[{id:"harmony-voiceleading-01-q1",type:"mcq",prompt:"Smooth voice leading generally prefers:",difficulty:5,choices:[{id:"a",text:"Small melodic steps and retaining common tones between chords",correct:!0},{id:"b",text:"Large leaps in every voice on every change"},{id:"c",text:"All voices moving in parallel octaves always"},{id:"d",text:"Random chord tones with no regard for spacing"}],explain:"Stepwise motion and shared notes connect harmonies and keep independent lines intelligible."},{id:"harmony-voiceleading-01-q2",type:"mcq",prompt:"Contrary motion means:",difficulty:5,choices:[{id:"a",text:"One voice rises while another falls",correct:!0},{id:"b",text:"All voices move in the same direction"},{id:"c",text:"Only the bass may move"},{id:"d",text:"Voices must repeat the same pitch"}],explain:"Contrary motion between outer voices (soprano and bass) helps maintain balance and independence in texture."}]},{id:"harmony-cadences-01",title:"Cadences: Full, Half, Plagal, and Deceptive",track:"harmony",kind:"theory_lesson",difficulty:5,tags:["cadences","phrasing","harmony"],prerequisites:["harmony-tendency-01"],estimateMinutes:5,body:"A cadence is a harmonic punctuation mark at a phrase end. An authentic (full) cadence moves V\u2192I (or V7\u2192I) and feels like a firm full stop \u2014 common at the end of a tune part. A half cadence lands on V and feels like a comma or question, often at the midpoint of a strain before the repeat.\n\nA plagal cadence (IV\u2192I, the \u201camen\u201d cadence) softens an ending after the dominant has already appeared. A deceptive cadence moves V\u2192vi instead of V\u2192I, surprising the ear \u2014 less common in straight dance tunes but useful in songs and airs. Recognising cadence types helps you breathe and bow with the architecture of the melody.\n\nIn AABB tunes, the A part often half-cadences before the repeat while the B part authentic-cadences home. Accompanists who push dominant harmony too early can steal the half cadence\u2019s lift. Mark cadence points when learning a new reel and your phrasing will match experienced session players faster.",tryThis:"",quizzes:[{id:"harmony-cadences-01-q1",type:"mcq",prompt:"A V\u2192I progression at a phrase end is called:",difficulty:5,choices:[{id:"a",text:"An authentic (full) cadence",correct:!0},{id:"b",text:"A half cadence"},{id:"c",text:"A deceptive cadence"},{id:"d",text:"A plagal cadence only"}],explain:"Dominant to tonic (V\u2192I) is the classic authentic cadence, providing strong closure."},{id:"harmony-cadences-01-q2",type:"mcq",prompt:"A half cadence typically ends on which chord?",difficulty:5,choices:[{id:"a",text:"V (dominant)",correct:!0},{id:"b",text:"I (tonic)"},{id:"c",text:"vi (submediant)"},{id:"d",text:"iv (subdominant) only in minor"}],explain:"Half cadences pause on the dominant, creating expectation without full resolution to tonic."}]},{id:"harmony-phrases-01",title:"Phrase Structure in Tunes and Songs",track:"harmony",kind:"theory_lesson",difficulty:4,tags:["phrasing","form","analysis"],prerequisites:["harmony-cadences-01"],estimateMinutes:5,body:"Musical phrases are coherent chunks of melody, often four or eight bars, ending with a cadence. Irish dance tunes frequently use two-bar cells grouped into eight-bar parts. Songs may use question\u2013answer phrasing: bars 1\u20134 rise or open, bars 5\u20138 settle toward tonic.\n\nAntecedent and consequent phrases pair so the first asks and the second answers harmonically. In \u201cThe Star of the County Down,\u201d phrase endings often alternate weaker and stronger cadences. Mapping phrases reveals where to breathe, where to add variation on the repeat, and where percussion might mark a turn.\n\nHarmonic rhythm \u2014 how often chords change \u2014 interacts with phrase length. A tune with one chord per bar feels different from one that stays on I for four bars then shifts. When arranging, align chord changes with phrase boundaries unless you deliberately syncopate against them for effect.",tryThis:"",quizzes:[{id:"harmony-phrases-01-q1",type:"mcq",prompt:"An eight-bar strain in many dance tunes often divides into:",difficulty:4,choices:[{id:"a",text:"Two four-bar phrases",correct:!0},{id:"b",text:"Eight one-bar phrases with no grouping"},{id:"c",text:"One sixteen-bar phrase"},{id:"d",text:"Three equal three-bar phrases"}],explain:"Four-plus-four bar grouping is standard in reels, jigs, and hornpipes, often with a cadence at the midpoint and end."},{id:"harmony-phrases-01-q2",type:"truefalse",prompt:"Phrase endings often coincide with cadence points in the harmony.",difficulty:4,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Melodic phrase boundaries typically align with harmonic cadences, giving listeners a sense of punctuation."}]},{id:"harmony-secondary-01",title:"Secondary Dominants and Tonicisation",track:"harmony",kind:"theory_lesson",difficulty:7,tags:["secondary-dominants","tonicisation","harmony"],prerequisites:["chords-sevenths-01","harmony-cadences-01"],estimateMinutes:6,body:"A secondary dominant temporarily treats a non-tonic chord as a local key centre. In C major, A7 is V7/vi because it resolves to Dm (vi). D7 is V7/V, pulling to G. These chords introduce accidentals not in the home key signature \u2014 A7 brings C\u266f into C major.\n\nSecondary dominants add directional colour in songs and arranged trad medleys without full modulation. You might hear V7/vi\u2192vi as a brief brightening before returning to I. They appear in O\u2019Carolan arrangements, ragtime-influenced hornpipes, and contemporary folk songwriting.\n\nLabel secondary dominants by the chord they target: \u201cfive of six\u201d means dominant seventh on the note a fifth above the vi root. If the melody suddenly sharpens a note outside the key signature for one bar, suspect a secondary dominant or modal mixture rather than a full key change.",tryThis:"",quizzes:[{id:"harmony-secondary-01-q1",type:"mcq",prompt:"In C major, which chord functions as V7/vi (dominant of vi)?",difficulty:7,choices:[{id:"a",text:"A7",correct:!0},{id:"b",text:"E7"},{id:"c",text:"G7"},{id:"d",text:"F7"}],explain:"vi in C is Dm; the dominant a fifth above D is A, so A7 tonicises D minor before resolving."},{id:"harmony-secondary-01-q2",type:"mcq",prompt:"Secondary dominants typically introduce:",difficulty:7,choices:[{id:"a",text:"Accidentals foreign to the home key signature",correct:!0},{id:"b",text:"Only notes from the home major scale"},{id:"c",text:"Silence between sections"},{id:"d",text:"A change of time signature"}],explain:"To act as V7 of a target chord, the secondary dominant often needs a raised third (and other tendency tones) outside the home key."}]},{id:"harmony-modulation-01",title:"Modulation: Changing Key Mid-Tune",track:"harmony",kind:"theory_lesson",difficulty:8,tags:["modulation","keys","advanced"],prerequisites:["harmony-secondary-01","keys-circle-01"],estimateMinutes:7,body:"Modulation means establishing a new tonic, not merely touching foreign chords. Common moves include up a whole step (G\u2192A) for energy, to the relative minor (G\u2192Em), or by common chord (pivot) shared by two keys \u2014 C major serves as IV in G and I in C.\n\nDirect modulation jumps without preparation, often at a section break in arranged sets. Chromatic modulation uses a voice chromatically altered to slip into a new key. In trad, full modulations are less common in core repertoire than in c\xe9il\xed band arrangements or song verses, but key changes appear in medleys and competition sets.\n\nDetect modulation by sustained new accidentals and cadences confirming a new tonic. A single A7 in D major is tonicisation; four bars solidly in A with cadence to A is modulation. Accompanists should agree on whether a B part modulates or merely borrows chords before the repeat.",tryThis:"",quizzes:[{id:"harmony-modulation-01-q1",type:"mcq",prompt:"A pivot-chord modulation uses:",difficulty:8,choices:[{id:"a",text:"A chord that belongs to both the old and new keys as a bridge",correct:!0},{id:"b",text:"Only silence between keys"},{id:"c",text:"A tempo change without harmonic change"},{id:"d",text:"Random accidentals with no cadence"}],explain:"A common chord is reinterpreted in the new key (e.g., G major as V in C and I in G) to smooth the transition."},{id:"harmony-modulation-01-q2",type:"truefalse",prompt:"Modulation establishes a new tonic, whereas tonicisation is a brief visit without full key change.",difficulty:8,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Tonicisation highlights a chord temporarily via secondary dominants; modulation settles into a new key centre."}]},{id:"harmony-counterpoint-01",title:"Counterpoint: Independent Melodic Lines",track:"harmony",kind:"theory_lesson",difficulty:9,tags:["counterpoint","polyphony","advanced"],prerequisites:["harmony-voiceleading-01"],estimateMinutes:7,body:"Counterpoint is the art of combining melodies so each line remains musically intelligible while harmonising together. Species counterpoint (Gradus ad Parnassum tradition) trains stepwise motion, consonance on strong beats, and careful treatment of dissonance \u2014 skills that underpin Bach fugues and also inform twin-fiddle harmony.\n\nContrary and oblique motion between lines maintain independence; excessive parallel motion makes lines blur. In Irish trad, counterpoint appears in pipe regulators, harp bass lines, and twin-fiddle arrangements where the second player weaves a countermelody below the tune. The lines need not move in rhythmic unison; off-beat counter figures add lift.\n\nStrict academic rules relax in oral tradition, but the ear still prefers consonant intervals on downbeats and clear resolution of dissonance. When writing a harmony part, sing both lines separately: if either sounds like random notes, simplify until each stands alone.",tryThis:"",quizzes:[{id:"harmony-counterpoint-01-q1",type:"mcq",prompt:"The main goal of counterpoint is:",difficulty:9,choices:[{id:"a",text:"Combine independent melodic lines that remain coherent individually",correct:!0},{id:"b",text:"Play the same melody in unison always"},{id:"c",text:"Eliminate all dissonance on every beat"},{id:"d",text:"Replace harmony with percussion only"}],explain:"Counterpoint balances horizontal melody writing with vertical consonance, keeping each voice musically meaningful."},{id:"harmony-counterpoint-01-q2",type:"mcq",prompt:"Contrary motion in two-part writing means:",difficulty:9,choices:[{id:"a",text:"One line ascends while the other descends",correct:!0},{id:"b",text:"Both lines use identical rhythm and direction always"},{id:"c",text:"Only one line may contain notes"},{id:"d",text:"Both lines must end on the same pitch"}],explain:"Contrary motion preserves independence between voices and is a cornerstone of classical counterpoint technique."}]}]).concat([{id:"history-bach-01",title:"J.S. Bach: Counterpoint and Dance Forms",track:"history",kind:"theory_lesson",difficulty:3,tags:["bach","baroque","history"],prerequisites:[],estimateMinutes:5,body:"Johann Sebastian Bach (1685\u20131750) worked in German churches and courts, composing fugues, chorales, suites, and partitas that remain central to Western music education. His Well-Tempered Clavier demonstrated that keyboard music could move through all major and minor keys \u2014 a direct ancestor of how we think about the circle of fifths today.\n\nBach absorbed dance rhythms \u2014 allemandes, gigues, minuets \u2014 into instrumental suites. Trad musicians care about Bach because his part-writing clarifies how independent lines fit together, skills transferable to twin-fiddle harmony or pipe regulator accompaniment. His ornament tables also influenced how baroque-influenced harp and classical flute players approach gracing.\n\nYou need not play Bach to benefit from him: studying one two-part invention shows how a bass line can imply harmony while the right hand sings melody \u2014 the same split session guitarists and pianists use behind a tune.",tryThis:"",quizzes:[{id:"history-bach-01-q1",type:"mcq",prompt:"Bach\u2019s Well-Tempered Clavier is especially famous for:",difficulty:3,choices:[{id:"a",text:"Preludes and fugues in all major and minor keys",correct:!0},{id:"b",text:"Inventing the tin whistle"},{id:"c",text:"Writing only jazz standards"},{id:"d",text:"Composing exclusively for electric guitar"}],explain:"The 48 preludes and fugues cycle through the keys, a landmark of baroque keyboard craft and equal-temperament thinking."},{id:"history-bach-01-q2",type:"truefalse",prompt:"Bach incorporated dance forms such as gigues into his instrumental suites.",difficulty:3,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Baroque suites commonly ended with gigues and included other court dances, linking Bach to the broader European dance tradition."}]},{id:"history-mozart-01",title:"Mozart: Clarity, Balance, and Melody",track:"history",kind:"theory_lesson",difficulty:3,tags:["mozart","classical","history"],prerequisites:[],estimateMinutes:5,body:"Wolfgang Amadeus Mozart (1756\u20131791) wrote symphonies, operas, chamber music, and piano works with effortless melodic balance. Classical-era ideals \u2014 clear phrases, balanced antecedent/consequent structure, and transparent harmony \u2014 appear throughout his music and still shape how we hear \u201cwell-formed\u201d tunes.\n\nFolk musicians encounter Mozart through classical flute repertoire, string quartet arrangements of trad tunes, and the idea that a melody should breathe in even four-bar units. His piano sonatas illustrate Alberti bass patterns and simple I\u2013V\u2013I harmonic motion that underpin countless songs.\n\nMozart matters practically because his phrasing model helps you shape airs and slow sessions tunes: lift at the midpoint cadence, settle at the authentic cadence, and keep inner rhythm steady even when ornamenting.",tryThis:"",quizzes:[{id:"history-mozart-01-q1",type:"mcq",prompt:"Mozart is associated with which broad musical era?",difficulty:3,choices:[{id:"a",text:"Classical era",correct:!0},{id:"b",text:"Baroque era only"},{id:"c",text:"20th-century serialism"},{id:"d",text:"Electric blues"}],explain:"Mozart\u2019s career sits in the late Classical period, between Baroque complexity and Romantic expressiveness."},{id:"history-mozart-01-q2",type:"mcq",prompt:"Why might a trad player study Mozart\u2019s phrasing?",difficulty:3,choices:[{id:"a",text:"His clear four-bar phrases model breathing and cadence points",correct:!0},{id:"b",text:"He invented the uilleann pipes"},{id:"c",text:"He wrote only in 7/8 time"},{id:"d",text:"He rejected all dance rhythms"}],explain:"Classical phrase symmetry helps musicians shape slow airs and songs with intentional cadences and balanced lines."}]},{id:"history-beethoven-01",title:"Beethoven: Drama, Form, and Expansion",track:"history",kind:"theory_lesson",difficulty:4,tags:["beethoven","romantic","history"],prerequisites:[],estimateMinutes:5,body:"Ludwig van Beethoven (1770\u20131827) bridged Classical and Romantic styles, expanding form and emotional range in symphonies, sonatas, and string quartets. He stretched development sections, intensified dynamic contrasts, and made motivic cells \u2014 short rhythmic or melodic ideas \u2014 drive entire movements.\n\nTrad players feel Beethoven\u2019s influence when arrangements add dramatic key changes, sudden dynamic shifts, or developmental variation on a repeated tune part. His emphasis on rhythmic motive (think of the Fifth Symphony opening) parallels how reel pick-up notes and rhythmic drive define dance music.\n\nBeethoven also championed music as personal expression rather than pure court entertainment. That ethos echoes in folk revival movements where community musicians claim ownership of repertoire, not only virtuoso elites.",tryThis:"",quizzes:[{id:"history-beethoven-01-q1",type:"mcq",prompt:"Beethoven is often described as bridging which two stylistic periods?",difficulty:4,choices:[{id:"a",text:"Classical and Romantic",correct:!0},{id:"b",text:"Medieval and Renaissance"},{id:"c",text:"Baroque and jazz"},{id:"d",text:"Minimalism and hip-hop"}],explain:"Beethoven\u2019s early works follow Classical models; his later works expand form and expression toward Romantic ideals."},{id:"history-beethoven-01-q2",type:"truefalse",prompt:"Beethoven frequently built large forms from small recurring motives.",difficulty:4,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Motivic development \u2014 spinning entire movements from brief ideas \u2014 is a hallmark of Beethoven\u2019s compositional method."}]},{id:"history-chopin-01",title:"Chopin: Piano Colour and Rubato",track:"history",kind:"theory_lesson",difficulty:4,tags:["chopin","piano","history"],prerequisites:[],estimateMinutes:5,body:"Fr\xe9d\xe9ric Chopin (1810\u20131849) composed almost exclusively for piano, creating nocturnes, mazurkas, polonaises, and \xe9tudes that redefine touch and colour at the instrument. His music privileges singing right-hand lines over harmonic accompaniment patterns in the left hand \u2014 a texture folk pianists mimic when backing slow airs.\n\nChopin\u2019s use of rubato \u2014 flexible timing within a steady pulse \u2014 connects to oral-tradition phrasing where melody breathes while rhythm section holds tempo. His mazurkas also show how national dance rhythms (Polish triple meter with accent shifts) can live inside concert music, much as Irish dances live inside both kitchen sessions and staged recitals.\n\nEven non-classical players gain from Chopin: voicing chords so melody floats above, pedalling sparingly in dance halls, and treating ornaments as expressive rather than mechanical.",tryThis:"",quizzes:[{id:"history-chopin-01-q1",type:"mcq",prompt:"Chopin is most closely associated with which instrument?",difficulty:4,choices:[{id:"a",text:"Piano",correct:!0},{id:"b",text:"Bagpipes"},{id:"c",text:"Electric bass"},{id:"d",text:"Synthesizer"}],explain:"Chopin\u2019s catalogue is overwhelmingly piano music, shaping Romantic keyboard technique and expression."},{id:"history-chopin-01-q2",type:"mcq",prompt:"Rubato in Chopin\u2019s tradition generally means:",difficulty:4,choices:[{id:"a",text:"Flexible timing in the melody while overall pulse remains",correct:!0},{id:"b",text:"Playing as fast as possible"},{id:"c",text:"Ignoring harmony entirely"},{id:"d",text:"Strict metronomic equality on every note"}],explain:"Rubato stretches and releases melodic time expressively without losing the underlying rhythmic framework."}]},{id:"history-debussy-01",title:"Debussy: Colour, Modes, and New Sonorities",track:"history",kind:"theory_lesson",difficulty:5,tags:["debussy","impressionism","history"],prerequisites:[],estimateMinutes:5,body:"Claude Debussy (1862\u20131918) broke from functional Germanic harmony toward colour, parallel motion, and modal scales. Pieces like \u201cPr\xe9lude \xe0 l\u2019apr\xe8s-midi d\u2019un faune\u201d treat chords as sonorities rather than strict voice-leading targets, influencing film music and contemporary folk arranging.\n\nDebussy drew on whole-tone and pentatonic collections that feel familiar to players of Celtic and Asian-influenced tunes. His avoidance of heavy dominant-tonic cadences parallels modal Irish melodies that centre on a pitch without constant V\u2013I motion. Harp and piano players arranging airs borrow Debussy\u2019s voicing spacing \u2014 wide gaps, soft doublings \u2014 for atmospheric intros.\n\nUnderstanding Debussy helps when a tune \u201cfloats\u201d harmonically: you may colour with parallel triads or planing chords instead of forcing classical cadences where the melody never asked for them.",tryThis:"",quizzes:[{id:"history-debussy-01-q1",type:"mcq",prompt:"Debussy\u2019s harmony is often described as favouring:",difficulty:5,choices:[{id:"a",text:"Colour and sonority over strict functional progression",correct:!0},{id:"b",text:"Strict Bach-style fugues exclusively"},{id:"c",text:"Only twelve-tone serial rows"},{id:"d",text:"Unison brass band scoring only"}],explain:"Impressionist harmony emphasises timbre and modal colour rather than relentless dominant-tonic drive."},{id:"history-debussy-01-q2",type:"truefalse",prompt:"Whole-tone and pentatonic scales appear in Debussy\u2019s language and also in many folk traditions.",difficulty:5,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Debussy\u2019s scales overlap with folk and non-Western collections, blurring the line between art music and oral tradition."}]},{id:"history-armstrong-01",title:"Louis Armstrong: Swing, Phrasing, and Improvisation",track:"history",kind:"theory_lesson",difficulty:4,tags:["armstrong","jazz","history"],prerequisites:[],estimateMinutes:5,body:"Louis Armstrong (1901\u20131971) transformed jazz from collective New Orleans polyphony into virtuoso solo trumpet and vocal phrasing. His recordings in the 1920s with the Hot Five and Hot Seven set templates for swing rhythm, blues inflection, and improvising on chord changes.\n\nFolk musicians hear Armstrong\u2019s legacy in swung hornpipes, jazz-waltz sessions, and any tune where the melody player \u201cplays behind the beat\u201d then catches up. His vocal scat lines treat pitch and rhythm as equal expressive tools \u2014 not unlike sean-n\xf3s or Appalachian ornament that bends time.\n\nArmstrong also modelled storytelling in a single chorus: start simple, build intensity, land a memorable ending. That arc applies to variation on the repeat in Irish dance music, even without jazz harmony.",tryThis:"",quizzes:[{id:"history-armstrong-01-q1",type:"mcq",prompt:"Louis Armstrong was a pioneering virtuoso on:",difficulty:4,choices:[{id:"a",text:"Trumpet (and voice)",correct:!0},{id:"b",text:"Harpsichord"},{id:"c",text:"Uilleann pipes"},{id:"d",text:"Sitar"}],explain:"Armstrong\u2019s trumpet solos and gravelly vocals defined early jazz solo style and swing phrasing."},{id:"history-armstrong-01-q2",type:"mcq",prompt:"\u201cSwing\u201d in Armstrong\u2019s era refers to:",difficulty:4,choices:[{id:"a",text:"A rhythmic feel that subdivides the beat with bounce and syncopation",correct:!0},{id:"b",text:"Playing exactly on the metronome with no deviation"},{id:"c",text:"A type of classical opera"},{id:"d",text:"Only 6/8 jig rhythm"}],explain:"Swing places emphasis flexibly within the beat, creating the propulsive lilt central to jazz and related folk fusion."}]},{id:"history-ellington-01",title:"Duke Ellington: Band Colour and Composition",track:"history",kind:"theory_lesson",difficulty:5,tags:["ellington","jazz","history"],prerequisites:[],estimateMinutes:5,body:"Duke Ellington (1899\u20131974) led one of the greatest big bands, composing thousands of pieces that treat each section \u2014 reeds, brass, rhythm \u2014 as a palette of colour. \u201cMood Indigo,\u201d \u201cTake the A Train,\u201d and extended suites show how arrangement equals composition.\n\nTrad musicians benefit from Ellington\u2019s lesson that harmony is orchestration: the same chord voiced differently changes the room. C\xe9il\xed bands and folk big bands borrow this when assigning countermelodies to accordion versus fiddle versus brass. Ellington also wrote for dancers, linking jazz to social dance like trad links tunes to sets.\n\nStudy Ellington when arranging medleys: vary texture each turn, give soloists space over rich backgrounds, and use shout choruses for climax \u2014 techniques transferable to festival sets.",tryThis:"",quizzes:[{id:"history-ellington-01-q1",type:"mcq",prompt:"Duke Ellington is best known as a:",difficulty:5,choices:[{id:"a",text:"Bandleader and composer of jazz orchestra music",correct:!0},{id:"b",text:"Baroque organ specialist only"},{id:"c",text:"Silent-film pianist exclusively"},{id:"d",text:"Heavy-metal guitarist"}],explain:"Ellington\u2019s orchestra and compositions are cornerstones of American jazz, emphasising sectional colour and arrangement."},{id:"history-ellington-01-q2",type:"truefalse",prompt:"Ellington treated individual band sections as distinct colours in his arrangements.",difficulty:5,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Ellington wrote parts tailored to specific players and sections, making orchestration central to his sound."}]},{id:"history-parker-01",title:"Charlie Parker: Bebop and Harmonic Velocity",track:"history",kind:"theory_lesson",difficulty:6,tags:["parker","bebop","history"],prerequisites:[],estimateMinutes:5,body:"Charlie \u201cBird\u201d Parker (1920\u20131955) revolutionised jazz alto saxophone with bebop \u2014 fast harmonic rhythm, chromatic passing tones, and improvising on chord changes rather than melody alone. Tunes like \u201cConfirmation\u201d and \u201cBlues for Alice\u201d became \xe9tudes for jazz musicians worldwide.\n\nBebop\u2019s chord sophistication influenced folk-jazz crossover: backing a reel with ii\u2013V\u2013I substitutions or altered dominants traces to Parker\u2019s generation even when players never play jazz gigs. Bird also shows how oral tradition plus rigorous practice (hours of technique daily) produces new vocabulary within existing forms.\n\nFor trad players curious about improvisation, Parker demonstrates targeting chord tones on strong beats while using chromatic approaches between them \u2014 a method you can apply sparingly on modal tunes without full bebop velocity.",tryThis:"",quizzes:[{id:"history-parker-01-q1",type:"mcq",prompt:"Charlie Parker was a central figure in which jazz style?",difficulty:6,choices:[{id:"a",text:"Bebop",correct:!0},{id:"b",text:"Dixieland only"},{id:"c",text:"Smooth jazz of the 1980s"},{id:"d",text:"Gregorian chant"}],explain:"Parker, with Dizzy Gillespie and others, pioneered bebop\u2019s fast harmonic language and improvisational complexity."},{id:"history-parker-01-q2",type:"mcq",prompt:"Bebop improvisation typically emphasises:",difficulty:6,choices:[{id:"a",text:"Navigating chord changes with chromatic lines",correct:!0},{id:"b",text:"Playing only the written melody unchanged"},{id:"c",text:"Avoiding all seventh chords"},{id:"d",text:"Strict unison with no variation"}],explain:"Bebop soloists outline harmonies rapidly, using extensions and chromatic approaches between chord tones."}]},{id:"history-trad-collectors-01",title:"Collectors and Revivals: Saving Oral Tradition",track:"history",kind:"theory_lesson",difficulty:3,tags:["collectors","revival","trad"],prerequisites:[],estimateMinutes:5,body:"Without field collectors, much trad repertoire would be lost. Francis O\u2019Neill published thousands of Irish dance tunes from Chicago musicians; Cecil Sharp documented English morris and country dances; Alan Lomax and others recorded Appalachian ballads and blues. Their notebooks and 78rpm sessions became the tune books and archives we search today.\n\nCollectors did not merely transcribe \u2014 they shaped revival taste by what they chose to publish and how they harmonised melodies. Modern players owe them access but also critique sources: versions differ, titles drift, and printed keys may not match local practice.\n\nWhen you add a tune from abc2book or a PDF collection, you join a chain from kitchen player to collector to digital archive. Cite sources when possible and stay open to living players who remember alternate turns.",tryThis:"",quizzes:[{id:"history-trad-collectors-01-q1",type:"mcq",prompt:"Captain Francis O\u2019Neill is famous for:",difficulty:3,choices:[{id:"a",text:"Publishing large collections of Irish dance tunes",correct:!0},{id:"b",text:"Inventing the piano forte"},{id:"c",text:"Writing symphonies in Vienna"},{id:"d",text:"Founding bebop in New York"}],explain:"O\u2019Neill\u2019s \u201cMusic of Ireland\u201d and related volumes preserved thousands of tunes from Irish-American musicians."},{id:"history-trad-collectors-01-q2",type:"truefalse",prompt:"Field collectors helped preserve oral-tradition music that might otherwise have been lost.",difficulty:3,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Transcription and recording projects created durable records of tunes passed primarily by ear in community settings."}]},{id:"history-women-01",title:"Women in Music History: Composers and Tradition Bearers",track:"history",kind:"theory_lesson",difficulty:3,tags:["women","history","trad"],prerequisites:[],estimateMinutes:5,body:"Music history textbooks long underrepresented women, yet women composed, performed, collected, and carried traditions at every level. Hildegard of Bingen wrote visionary monophonic works; Clara Schumann concertised and composed; Fanny Mendelssohn\u2019s lieder circulated under her brother\u2019s name. In trad music, women singers and dancers often preserved repertoire in domestic settings while public stages were restricted.\n\nContemporary players benefit from recovering these voices: harpist composers like Turlough O\u2019Carolan sit beside lesser-known women tune-writers and song carriers documented in regional archives. Festivals now highlight women pipers, fiddlers, and accordionists who were always in sessions but rarely featured on album covers.\n\nSeeking diverse sources improves your repertoire and your ensemble culture. When arranging historical music, ask who is missing from the printed page \u2014 the answer often leads to richer sets and fairer credit.",tryThis:"",quizzes:[{id:"history-women-01-q1",type:"mcq",prompt:"Clara Schumann was known primarily as a:",difficulty:3,choices:[{id:"a",text:"Pianist and composer",correct:!0},{id:"b",text:"Baroque trumpet maker"},{id:"c",text:"Disc jockey"},{id:"d",text:"Silent-film projectionist"}],explain:"Clara Schumann was a leading 19th-century pianist who also composed songs and chamber works."},{id:"history-women-01-q2",type:"truefalse",prompt:"Women have historically participated in carrying oral-tradition music even when underrepresented in published collections.",difficulty:3,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Domestic and community settings often relied on women singers and musicians whose contributions were less documented than male public performers."}]}]).concat([{id:"styles-baroque-01",title:"Baroque Style: Ornament, Continuo, and Dance",track:"styles",kind:"theory_lesson",difficulty:4,tags:["baroque","style","ornament"],prerequisites:[],estimateMinutes:5,body:"Baroque music (roughly 1600\u20131750) favours continuous motion, clear bass lines, and figured-harmony accompaniment (basso continuo). Ornamentation is expected: trills, mordents, and appoggiaturas are not optional fluff but part of the style. Harpsichord and baroque violin treatises describe when to grace cadences and how to vary repeats.\n\nDance suites anchor much instrumental baroque repertoire \u2014 allemande, courante, sarabande, gigue \u2014 linking court culture to village dance roots. O\u2019Carolan\u2019s harp music and baroque flute arrangements of trad tunes sit in this world of patterned basses and melodic variation on the repeat.\n\nIf you play baroque-influenced sets, practise grounding tempo with a steady bass while melody ornaments lightly. Over-ornamenting early repeats leaves nowhere to go; save intensity for the second time through.",tryThis:"",quizzes:[{id:"styles-baroque-01-q1",type:"mcq",prompt:"Basso continuo in baroque music refers to:",difficulty:4,choices:[{id:"a",text:"A bass line with harmonic figures filled in by keyboard or lute",correct:!0},{id:"b",text:"A capo on the second fret"},{id:"c",text:"Unaccompanied solo whistle"},{id:"d",text:"Strictly percussion-only accompaniment"}],explain:"Continuo players realise chords from a bass line and figures, supporting melody instruments in baroque ensemble texture."},{id:"styles-baroque-01-q2",type:"truefalse",prompt:"Ornamentation was considered an expected part of baroque performance practice.",difficulty:4,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Baroque treatises document standard ornaments and when to apply them, especially on cadences and repeated sections."}]},{id:"styles-classical-01",title:"Classical Style: Balance and Sonata Form",track:"styles",kind:"theory_lesson",difficulty:4,tags:["classical","style","form"],prerequisites:[],estimateMinutes:5,body:"Classical-era music (roughly 1750\u20131820) values symmetry, homophonic texture (melody with accompaniment), and clearly articulated phrases. Sonata form \u2014 exposition, development, recapitulation \u2014 organises longer works, but the same question\u2013answer phrase logic appears in short dance tunes and song verses.\n\nDynamic shading stays within classical norms: sudden forte surprises exist but less extreme than Romantic extremes. Alberti bass and broken-chord accompaniment patterns support singable top lines. String quartets from Haydn and Mozart model how four friends converse musically \u2014 a metaphor for good session listening.\n\nClassical clarity helps arrangers of trad tunes: if everyone ornaments differently at once, texture muddies. Classical balance suggests varying one layer at a time while others hold steady.",tryThis:"",quizzes:[{id:"styles-classical-01-q1",type:"mcq",prompt:"Classical texture often features:",difficulty:4,choices:[{id:"a",text:"A clear melody with accompaniment (homophony)",correct:!0},{id:"b",text:"Only unstructured noise"},{id:"c",text:"Exclusive use of 7/8 meter"},{id:"d",text:"No phrase structure at all"}],explain:"Classical style typically foregrounds a primary melody supported by simpler harmonic accompaniment."},{id:"styles-classical-01-q2",type:"mcq",prompt:"Sonata form includes which large sections?",difficulty:4,choices:[{id:"a",text:"Exposition, development, recapitulation",correct:!0},{id:"b",text:"Intro, verse, chorus, bridge only"},{id:"c",text:"Only a coda with no main material"},{id:"d",text:"Twelve-bar blues exclusively"}],explain:"Sonata form presents themes, develops them through key change and fragmentation, then returns in the home key."}]},{id:"styles-romantic-01",title:"Romantic Style: Expression and Expanded Harmony",track:"styles",kind:"theory_lesson",difficulty:5,tags:["romantic","style","expression"],prerequisites:[],estimateMinutes:5,body:"Romantic music (19th century) stretches forms for emotional narrative: bigger orchestras, richer chromatic harmony, and virtuoso solo writing. Chopin nocturnes, Brahms intermezzi, and Liszt transcriptions show harmony colouring mood as much as defining function.\n\nFolk players feel Romantic influence in slow air arrangements with lush piano introductions, key changes for drama in c\xe9il\xed band sets, and vibrato-heavy string treatment of song melodies. Nationalist composers (Dvo\u0159\xe1k, Grieg) embedded folk dances in symphonic guise, legitimising trad sources for concert audiences.\n\nRomantic harmony tools \u2014 borrowed chords, augmented sixths, extended dominants \u2014 appear sparingly in trad but colour contemporary folk songwriting. Use them where the story needs shadow; not every reel wants a Rachmaninoff ending.",tryThis:"",quizzes:[{id:"styles-romantic-01-q1",type:"mcq",prompt:"Romantic-era music is often characterised by:",difficulty:5,choices:[{id:"a",text:"Expanded emotional expression and richer harmony",correct:!0},{id:"b",text:"Strict avoidance of all dynamics"},{id:"c",text:"Exclusive use of plainchant"},{id:"d",text:"No solo instrumental roles"}],explain:"Romantic composers pursued personal expression through larger forces, chromatic harmony, and virtuosic writing."},{id:"styles-romantic-01-q2",type:"truefalse",prompt:"Nationalist Romantic composers sometimes incorporated folk dance material into orchestral works.",difficulty:5,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Composers like Dvo\u0159\xe1k and Grieg quoted folk melodies and dances, bridging oral tradition and concert hall."}]},{id:"styles-folk-dances-01",title:"Reels, Jigs, Waltzes, and Hornpipes",track:"styles",kind:"theory_lesson",difficulty:2,tags:["dance","reel","jig","waltz","hornpipe"],prerequisites:["foundations-rhythm-01"],estimateMinutes:6,body:"Irish and Scottish session dance types each carry a distinct pulse. Reels are in 2/2 or 4/4 with a steady driving beat \u2014 think \u201cONE-two THREE-four\u201d at moderate to fast tempo. Double jigs are in 6/8 with two beats per bar grouped as three eighth notes each: \u201cJIG-ged-y JIG-ged-y.\u201d Single jigs and slides use 12/8 variants in some regions.\n\nWaltzes sit in 3/4 with a strong first beat: \u201cONE-two-three.\u201d Hornpipes often use dotted rhythm (long-short pairs) and swing, commonly notated in 4/4 with a slower, bouncy feel. Not every hornpipe is dotted in every region, but the caricature long-short pattern is a reliable clue when learning by ear.\n\nMatching your foot tap to the dance type prevents dragging a reel like a jig. When joining a set, listen one round for meter before playing \u2014 the best session etiquette you can bring.",tryThis:"",quizzes:[{id:"styles-folk-dances-01-q1",type:"mcq",prompt:"A standard double jig is most commonly notated in:",difficulty:2,choices:[{id:"a",text:"6/8 time",correct:!0},{id:"b",text:"3/4 waltz time"},{id:"c",text:"5/4 time"},{id:"d",text:"7/8 exclusively"}],explain:"Double jigs use compound 6/8 meter with two main beats per bar, each subdivided into three eighth notes."},{id:"styles-folk-dances-01-q2",type:"mcq",prompt:"Which dance type is typically associated with a steady 2/2 or 4/4 drive?",difficulty:2,choices:[{id:"a",text:"Reel",correct:!0},{id:"b",text:"Waltz"},{id:"c",text:"Double jig"},{id:"d",text:"Slow air only"}],explain:"Reels move in duple meter with an even, propulsive rhythm distinct from triple-time jigs and waltzes."}]},{id:"styles-blues-01",title:"Blues: Form, Scale, and Expression",track:"styles",kind:"theory_lesson",difficulty:4,tags:["blues","form","scale"],prerequisites:["chords-sevenths-01"],estimateMinutes:5,body:"Blues combines a repeating harmonic form, a distinctive scale, and expressive microtonal inflection. Twelve-bar blues cycles I\u2013IV\u2013V chords (often dominant sevenths) over twelve bars with standard turnarounds. Eight-bar and sixteen-bar blues variants appear in regional styles.\n\nThe blues scale adds a lowered third, lowered fifth, and lowered seventh to the minor pentatonic, allowing \u201cbetween the cracks\u201d pitches on guitar and voice. Bent notes mimic vocal cry \u2014 parallel to sean-n\xf3s pitch inflection and fiddle slides.\n\nBlues intersects folk when Appalachian ballads meet African American song forms, and when trad bands add shuffle rhythm to hornpipes. Knowing the twelve-bar map helps you jam on a three-chord song at a pub without a chart.",tryThis:"",quizzes:[{id:"styles-blues-01-q1",type:"mcq",prompt:"Classic twelve-bar blues primarily uses which harmonic functions?",difficulty:4,choices:[{id:"a",text:"I, IV, and V (often as dominant seventh chords)",correct:!0},{id:"b",text:"Only minor ii chords"},{id:"c",text:"Strictly one chord for all twelve bars"},{id:"d",text:"Only diminished seventh chains"}],explain:"Twelve-bar blues rotates through tonic, subdominant, and dominant harmonies in a familiar repeating pattern."},{id:"styles-blues-01-q2",type:"truefalse",prompt:"Blue notes often involve flattened third and seventh degrees with expressive pitch bending.",difficulty:4,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Blues inflection lowers certain scale degrees and bends pitch for expressive effect beyond fixed equal temperament."}]},{id:"styles-jazz-01",title:"Jazz Basics: Swing, Standards, and Changes",track:"styles",kind:"theory_lesson",difficulty:5,tags:["jazz","swing","standards"],prerequisites:["styles-blues-01","chords-sevenths-01"],estimateMinutes:6,body:"Jazz grew from blues, ragtime, and brass band traditions into a music centred on swing feel, improvisation, and chord progression literacy. Musicians learn standards (\u201cAutumn Leaves,\u201d \u201cAll the Things You Are\u201d) to share repertoire without sheet music, much as trad players share tune titles at sessions.\n\nLead sheets give melody and chord symbols; the rest is improvised. ii\u2013V\u2013I motion, tritone substitutions, and turnarounds appear constantly. Rhythm sections walk bass, comp chords on offbeats, and ride cymbal patterns define swing at medium tempo.\n\nFolk-jazz crossover uses jazz voicings on song accompaniment or adds improvised choruses between tune repeats. You do not need bebop velocity to participate \u2014 outline chord roots on strong beats and listen for where the soloist goes.",tryThis:"",quizzes:[{id:"styles-jazz-01-q1",type:"mcq",prompt:"A typical jazz \u201clead sheet\u201d provides:",difficulty:5,choices:[{id:"a",text:"Melody and chord symbols, with improvisation expected",correct:!0},{id:"b",text:"Fully written orchestral score with no improvisation"},{id:"c",text:"Lyrics only"},{id:"d",text:"Tablature without chord names"}],explain:"Lead sheets are shorthand: head melody plus changes, leaving arrangement and soloing to the performers."},{id:"styles-jazz-01-q2",type:"mcq",prompt:"ii\u2013V\u2013I progression is central to jazz because:",difficulty:5,choices:[{id:"a",text:"It creates strong harmonic motion toward the tonic",correct:!0},{id:"b",text:"It avoids all dominant chords"},{id:"c",text:"It replaces melody entirely"},{id:"d",text:"It only works in 6/8 jig time"}],explain:"Minor ii to dominant V resolving to I is the workhorse cadential pattern in jazz harmony."}]},{id:"styles-pop-01",title:"Pop Song Craft: Hooks, Verse-Chorus, and Production",track:"styles",kind:"theory_lesson",difficulty:3,tags:["pop","songwriting","form"],prerequisites:["chords-diatonic-major-01"],estimateMinutes:5,body:"Popular song since the 20th century favours memorable hooks, verse\u2013chorus form, and repeated four-chord loops (I\u2013V\u2013vi\u2013IV and variants). Folk singers borrow pop craft when writing originals or arranging trad songs for wider audiences \u2014 tight intros, clear choruses, and dynamic build into final chorus.\n\nProduction choices \u2014 acoustic versus electric instrumentation, doubling vocals, percussion entry on chorus \u2014 shape listener experience as much as harmony. Spotify-era folk often strips to guitar-vocal verse then adds bodhr\xe1n and fiddle on chorus for lift.\n\nUnderstanding pop form helps you cut a long ballad for a festival slot or place a trad tune in a set with pacing: slow verse-like intro, dance tune as \u201cchorus energy,\u201d return to song for balance.",tryThis:"",quizzes:[{id:"styles-pop-01-q1",type:"mcq",prompt:"Which progression is a common pop four-chord loop in major keys?",difficulty:3,choices:[{id:"a",text:"I\u2013V\u2013vi\u2013IV",correct:!0},{id:"b",text:"Only vii\xb0\u2013I repeated"},{id:"c",text:"Strictly IV\u2013IV\u2013IV\u2013IV"},{id:"d",text:"No chords, drone only"}],explain:"I\u2013V\u2013vi\u2013IV (and rotations like vi\u2013IV\u2013I\u2013V) underpins countless pop and folk-rock songs."},{id:"styles-pop-01-q2",type:"truefalse",prompt:"Verse\u2013chorus form alternates narrative sections with a repeated, high-energy chorus.",difficulty:3,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Pop songs typically contrast detailed verses with a catchy, repeatable chorus hook."}]},{id:"styles-modes-01",title:"Modes in Folk Practice",track:"styles",kind:"theory_lesson",difficulty:4,tags:["modes","dorian","mixolydian"],prerequisites:["scales-major-01","transpose-modes-01"],estimateMinutes:5,body:"Modes explain tunes that do not behave like textbook major or minor. Dorian has minor third but major sixth (D dorian: D E F G A B C D). Mixolydian has major third but lowered seventh (G mixolydian: G A B C D E F G). Aeolian matches natural minor; ionian matches major.\n\nIrish repertoire uses dorian and mixolydian colours constantly: \u201cBanish Misfortune\u201d is often analysed as A dorian; many D-centred tunes use C natural (mixolydian on D). Players describe these as \u201cminor with a major sixth\u201d or \u201cmajor with a flat seventh\u201d without Greek names \u2014 modes give the shared vocabulary.\n\nHarmonising modal tunes works best when you respect the characteristic note: do not sharp C in D mixolydian just because D major would. Mode-aware backup keeps sessions sounding authentic.",tryThis:"",quizzes:[{id:"styles-modes-01-q1",type:"mcq",prompt:"D dorian differs from D natural minor by having:",difficulty:4,choices:[{id:"a",text:"A major sixth (B natural instead of B\u266d)",correct:!0},{id:"b",text:"A lowered third"},{id:"c",text:"No fourth scale degree"},{id:"d",text:"An extra sharp on every note"}],explain:"Dorian keeps a minor third but raises the sixth degree compared to aeolian/natural minor."},{id:"styles-modes-01-q2",type:"mcq",prompt:"Mixolydian mode is like major except:",difficulty:4,choices:[{id:"a",text:"The seventh scale degree is lowered",correct:!0},{id:"b",text:"The third is lowered to minor"},{id:"c",text:"The fifth is always absent"},{id:"d",text:"It uses 6/8 meter only"}],explain:"Mixolydian matches major on degrees 1\u20136 but lowers the seventh, giving a dominant-flavoured tonic chord."}]},{id:"styles-modern-01",title:"Modern and Contemporary Folk Fusion",track:"styles",kind:"theory_lesson",difficulty:5,tags:["modern","fusion","contemporary"],prerequisites:["styles-jazz-01","styles-pop-01"],estimateMinutes:5,body:"Contemporary trad embraces electric instruments, loop pedals, minimalist repetition, and genre crossovers \u2014 Celtic punk, folktronica, Nordic folk metal, and acoustic singer-songwriter circuits. Groups like The Bothy Band, Altan, and Lankum (each in different eras) expanded harmony, instrumentation, and production while keeping tune cores recognisable.\n\nModern players sample archival field recordings, add synth pads under pipes, or write polymeter tunes that still launch a ceilidh dance. Copyright and credit matter more as tunes circulate on streaming platforms; citing composers and sources is part of modern practice.\n\nFusion succeeds when the trad pulse remains identifiable: if the reel groove survives the drum kit, the tune still calls dancers. Experiment outward from a solid unadorned version first \u2014 know the tradition you are stretching.",tryThis:"",quizzes:[{id:"styles-modern-01-q1",type:"mcq",prompt:"Successful folk fusion typically:",difficulty:5,choices:[{id:"a",text:"Keeps core trad rhythm and tune identity while adding new textures",correct:!0},{id:"b",text:"Removes all dance pulse entirely"},{id:"c",text:"Avoids naming tune sources"},{id:"d",text:"Requires abandoning acoustic instruments always"}],explain:"Fusion works when listeners still recognise the trad skeleton \u2014 melody and dance groove \u2014 beneath new arrangement layers."},{id:"styles-modern-01-q2",type:"truefalse",prompt:"Modern trad artists may use loop pedals, electric instruments, and production techniques.",difficulty:5,choices:[{id:"true",text:"True",correct:!0},{id:"false",text:"False"}],explain:"Contemporary folk ensembles routinely blend traditional repertoire with modern gear and studio production."}]}]),a=Array.isArray(n)?n:[],s={theory:o,singing:a,theoryModules:o,singingModules:a}}}]);
//# sourceMappingURL=199.3ebd3c2b.chunk.js.map